local function awaitKnit(Knit,timeout)
    local done,ok,reason=false,false,nil
    local worker=task.spawn(function()
        local called,result,detail=pcall(function()return Knit.OnStart():await()end)
        ok=called and result==true;reason=called and detail or result;done=true
    end)
    local deadline=os.clock()+timeout
    while not done and os.clock()<deadline do task.wait(.05)end
    if not done then pcall(task.cancel,worker)end
    assert(done and ok,"AUT Knit startup is not ready: "..tostring(reason or "timeout"))
end
