local collisions={}
local collisionGroups={}
local function restoreCollisions()
    for part,value in pairs(collisions)do if part.Parent then part.CanCollide=value end end
    table.clear(collisions)
    for part,value in pairs(collisionGroups)do if part.Parent then part.CollisionGroup=value end end
    table.clear(collisionGroups)
end
local function noclip(character)
    for _,part in ipairs(character:GetDescendants())do
        if part:IsA("BasePart")then
            if collisions[part]==nil then collisions[part]=part.CanCollide end
            if collisionGroups[part]==nil then collisionGroups[part]=part.CollisionGroup end
            if part.CollisionGroup~="BypassAll"then part.CollisionGroup="BypassAll"end
            if part.CanCollide then part.CanCollide=false end
        end
    end
end

