local function horizontal(a, b)
    local x, z = a.X-b.X, a.Z-b.Z
    return math.sqrt(x*x+z*z)
end
local function standingHeight(humanoid,root,character)
    if not humanoid or not root then return 3 end
    local value=humanoid.HipHeight+root.Size.Y/2
    if humanoid.RigType==Enum.HumanoidRigType.R6 then
        local leg=character and character:FindFirstChild("Left Leg")
        value+=leg and leg.Size.Y or 2
    end
    return value
end
local function pointDistance(a, b)
    local x,z = a.x-b.x,a.z-b.z
    return math.sqrt(x*x+z*z)
end
local function discFromPair(a,b)
    return {x=(a.x+b.x)/2,z=(a.z+b.z)/2,r=pointDistance(a,b)/2}
end
local function discFromTriple(a,b,c)
    local d=2*(a.x*(b.z-c.z)+b.x*(c.z-a.z)+c.x*(a.z-b.z))
    if math.abs(d)<0.0001 then return nil end
    local aa,bb,cc=a.x*a.x+a.z*a.z,b.x*b.x+b.z*b.z,c.x*c.x+c.z*c.z
    local x=(aa*(b.z-c.z)+bb*(c.z-a.z)+cc*(a.z-b.z))/d
    local z=(aa*(c.x-b.x)+bb*(a.x-c.x)+cc*(b.x-a.x))/d
    return {x=x,z=z,r=pointDistance({x=x,z=z},a)}
end
local function enclosing(points)
    local c
    for i,a in ipairs(points) do
        if not c or pointDistance(a,c)>c.r+0.01 then
            c={x=a.x,z=a.z,r=0}
            for j=1,i-1 do
                local b=points[j]
                if pointDistance(b,c)>c.r+0.01 then
                    c=discFromPair(a,b)
                    for k=1,j-1 do
                        local p=points[k]
                        if pointDistance(p,c)>c.r+0.01 then c=discFromTriple(a,b,p) or c end
                    end
                end
            end
        end
    end
    return c
end

