function S:Observe()
    local folder=living()
    if not folder then return end
    observations[self.mobName]=observations[self.mobName] or {}
    local nodes=observations[self.mobName]
    for _,m in ipairs(folder:GetChildren()) do
        if matches(m.Name) and isNPC(m) and not self.seen[m] then
            local h=m:FindFirstChildOfClass("Humanoid")
            local r=m:FindFirstChild("HumanoidRootPart")
            if h and h.Health>0 and (r or #nodes==0) then
                local position=r and r.Position or m:GetPivot().Position
                if position.Magnitude>5 and (h.Health>=h.MaxHealth or #nodes==0) then
                    self.seen[m]=true
                    local matched
                    for _,node in ipairs(nodes) do
                        if horizontal(position,Vector3.new(node.x,node.y,node.z))<25 then matched=node;break end
                    end
                    if matched then matched.weight=math.min(12,matched.weight+1)
                    elseif #nodes<48 then table.insert(nodes,{x=position.X,y=position.Y,z=position.Z,weight=1}) end
                end
            end
        end
    end
end

function S:PlanHome()

    self:Observe()
    if profiles[self.mobName].fixedHome then
        local position=profiles[self.mobName].fallback
        local map=self.mobName=="Curses" and workspace:FindFirstChild("Map")
        local travelPoints=map and map:FindFirstChild("FastTravelPoints")
        local desert=travelPoints and travelPoints:FindFirstChild("Desert")
        local marker=desert and desert:FindFirstChild("GroundCharge",true)
        if marker and marker:IsA("Attachment") then
            position=marker.WorldPosition+Vector3.new(0,standingHeight(self.humanoid,self.root,self.character),0)
        end
        self.home=CFrame.new(position)
        self.groundResolved=self.mobName=="Curses";self.homeNodes=nil;self.coverage=0
        for _,node in ipairs(observations[self.mobName] or {}) do
            if horizontal(self.home.Position,Vector3.new(node.x,node.y,node.z))<=self.radius then self.coverage+=node.weight end
        end
        record("fixed-home",self.home)
        return
    end
    local nodes=observations[self.mobName] or (self.mobName=="Thugs" and observations.Thug) or {}
    if #nodes==0 then
        self.home=CFrame.new(profiles[self.mobName].fallback)
        self.coverage=0;return
    end
    local best, bestWeight, bestCost = nil,-1,math.huge
    local function consider(p)
        local inside,weight,cost={},0,0
        for _,v in ipairs(nodes) do
            local d=pointDistance(p,v)
            if d<=self.planningRadius+0.01 then
                table.insert(inside,v);weight+=v.weight;cost+=d*d*v.weight
            end
        end
        if weight>bestWeight or (weight==bestWeight and cost<bestCost) then
            best,bestWeight,bestCost=inside,weight,cost
        end
    end
    for _,p in ipairs(nodes) do consider(p) end
    for i=1,#nodes do for j=i+1,#nodes do
        local a,b=nodes[i],nodes[j]
        local d=pointDistance(a,b)
        if d>0.01 and d<=2*self.planningRadius then
            local mx,mz=(a.x+b.x)/2,(a.z+b.z)/2
            local h=math.sqrt(math.max(0,self.planningRadius*self.planningRadius-d*d/4))
            local dx,dz=-(b.z-a.z)/d,(b.x-a.x)/d
            consider({x=mx+dx*h,z=mz+dz*h});consider({x=mx-dx*h,z=mz-dz*h})
        end
    end end
    local c=enclosing(best)
    local y,weight=0,0
    for _,p in ipairs(best) do y+=p.y*p.weight;weight+=p.weight end
    self.home=CFrame.new(c.x,y/math.max(1,weight),c.z)
    self.groundResolved=false
    self.coverage=bestWeight
    self.homeNodes=best
    self.homeSpread=c.r
    record("home",{x=c.x,y=self.home.Position.Y,z=c.z,coverage=bestWeight,spread=c.r,radius=self.radius})
end

