function S:InteractionPose(prompt,root)
    local attachment=prompt and prompt.Parent
    local position=root.Position
    if attachment and attachment:IsA("Attachment")and prompt
        and(position-attachment.WorldPosition).Magnitude>prompt.MaxActivationDistance then position=attachment.WorldPosition end
    return CFrame.new(position)*root.CFrame.Rotation
end
function S:AcquireActivity(owner)
    if self.lifecycleBusy or self.activityOwner then return nil end
    local pose=(self.phase=="attacking") and self.visual or self.root.CFrame
    local lease={owner=owner,phase=self.phase,active=self.active,pose=pose,character=self.character,generation=self.generation}
    self.activityOwner=owner;self.phase=owner
    return lease
end
function S:ReleaseActivity(lease)
    if self.activityOwner~=lease.owner then return end
    self.activityOwner=nil
    if self.generation~=lease.generation then return end
    if self.character==lease.character and self.root and self.root.Parent and player.Character==self.character then
        self.root.CFrame=lease.pose;self.root.AssemblyLinearVelocity=Vector3.zero
        self.phase=self.active and lease.phase or "off"
        if lease.owner=="resources"and not self.active then
            restoreCollisions();self.flightPosition=nil;self.root.Anchored=false
            self.root.AssemblyLinearVelocity=Vector3.zero;self.root.AssemblyAngularVelocity=Vector3.zero
        end
    else self.phase=self.active and "returning" or "off" end
end
