function S:ReturnTo(pose)
    if not pose then return end
    local c=player.Character;local r=c and c:FindFirstChild("HumanoidRootPart");local h=c and c:FindFirstChildOfClass("Humanoid")
    self.pendingReturnPose=pose
    if r and h and h.Health>0 then
        restoreCollisions();r.Anchored=false
        local landing=pose+Vector3.new(0,7,0)
        r.CFrame=landing;r.AssemblyLinearVelocity=Vector3.zero;r.AssemblyAngularVelocity=Vector3.zero
        task.spawn(function()pcall(function()player:RequestStreamAroundAsync(landing.Position,.75)end)end)
        self.pendingReturnPose=nil
    end
end
function S:StartManualFarm()

    if self.bossFarm and self.bossFarm.selected then return self.bossFarm:Start()end

    if self.active then return false end
    local c=player.Character;local root=c and c:FindFirstChild("HumanoidRootPart")
    self.manualReturnPose=root and root.CFrame;self.manualSession=true
    return self:Start()
end
function S:StopManualFarm(reason,stayHere)

    if self.bossFarm and self.bossFarm.running then self.bossFarm:Stop(reason)end

    local pose=self.manualReturnPose




    if self.mimic then self.mimic.enabled=false end
    self:Stop(reason or "panel switch")
    self.manualSession=false;self.manualReturnPose=nil
    if not stayHere then self:ReturnTo(pose)end
end
