    if self.bossFarm and self.bossFarm:IsBoss(name)then return self.bossFarm:Select(name)end
    if self.bossFarm then self.bossFarm:Stop("Manual mob selection");self.bossFarm.selected=nil end
    if not profiles[name]or self.mobName==name then return end




    self:SetMobName(name)
    if resume then return self:Start()end
end
function S:SetMobName(name)
    if not profiles[name]or self.mobName==name then return end
    if self.mobName=="Kuro"and self.farmPosition=="Top"then self.farmPosition="Down"end
    self:Stop("mob changed")

    self.mobName=name;self.home=nil
    if self.profileRadiusBefore then self.radius=self.profileRadiusBefore;self.profileRadiusBefore=nil end
    if  profiles[name].radius  then self.profileRadiusBefore=self.radius;self.radius=math.max(self.radius,profiles[name].radius)end
    if name=="Kuro"then self.farmPosition="Top"end
end
function S:PrepareBusoResetFallback()
    local c=player.Character;local r=c and c:FindFirstChild("HumanoidRootPart")
    if not r or not self.home then return false end

    r.CFrame=self:WaitingPose()+Vector3.new(166,self.height+8,0)
    r.AssemblyLinearVelocity=Vector3.zero;r.AssemblyAngularVelocity=Vector3.zero
    return true
end
function S:Start()
    if unloaded or self.active then return false,"already running" end
    self.pendingReturnPose=nil
    self:CancelAttackRequests()
    if self.mimic and self.mimic.current then self.mimic:Cancel("Farm settings changed") end
    self.active=true;self.phase="initializing";self.reason="running";self.generation+=1
    self.needRecovery=false;self.busy=false;self.lastAttack=0;self.kills=0;self.attackCount=0;self.character=nil;self.minRenderY=nil;self.maxRenderY=nil;self.flightPosition=nil
    local c=player.Character;local r=c and c:FindFirstChild("HumanoidRootPart")
    self.character=c;self.root=r;self.humanoid=c and c:FindFirstChildOfClass("Humanoid")
    if r and self.humanoid and self.humanoid.Health>0 then
        if not self.home then self:PlanHome()end
        r.CFrame=self:WaitingPose();r.AssemblyLinearVelocity=Vector3.zero;self.phase="returning"
    end
    if self.moves and self.moves.OnFarmStart then self.moves:OnFarmStart()end
    record("on",self.mobName)
    return true
end

function S:CancelAttackRequests()
    local current=coroutine.running()
    for _,request in pairs(self.attackRequests or{})do
        if request.worker and request.worker~=current then pcall(task.cancel,request.worker)end
    end
    self.attackQueued=false
    self.attackRequests={};self.busy=false
end
function S:Attack()
    self.attackQueued=true
end
function S:SendAttack()
    if self.moves and self.moves.TickKuroM1Guard and self.moves:TickKuroM1Guard()then return end
    if self.moves and self.moves.TickGolemGuard and self.moves:TickGolemGuard()then return end
    if self.moves and self.moves.TickWindGuard and self.moves:TickWindGuard()then return end

    self.attackRequests=self.attackRequests or{}
    local now=os.clock();local pending=0
    local move=self.moves and self.moves.action
    if move and(move.name=="Busoshoku Haki"or move.name=="Summon")then
        local character=player.Character
        local casting=character and character:GetAttribute("MoveActive")==true
        if casting or now-move.started<.2 then
            if self.moves.ReleaseBasicAttack then self.moves:ReleaseBasicAttack()end
            return
        end
    end
    if self.lifecycleBusy then
        if self.moves and self.moves.ReleaseBasicAttack then self.moves:ReleaseBasicAttack()end
        return
    end
    for ticket,request in pairs(self.attackRequests)do
        if request.generation~=self.generation or now-request.started>3 then
            if request.worker then pcall(task.cancel,request.worker)end
            self.inputTimeouts=(self.inputTimeouts or 0)+1
            self.attackRequests[ticket]=nil
        else pending+=1 end
    end
    self.busy=pending>0
    if self.moves and self.moves.ShouldPrioritizeMove and self.moves:ShouldPrioritizeMove()then
        if self.moves.ReleaseBasicAttack then self.moves:ReleaseBasicAttack()end
        return
    end

    if self.autoAttack==false or (not self.active and not(self.mimic and self.mimic.current)) or (self.phase~="attacking" and self.phase~="mimic")then
        if self.moves and self.moves.ReleaseBasicAttack then self.moves:ReleaseBasicAttack()end
        return
    end
    if pending>=2 then return end
    if self.moves and self.moves.BasicAttackDue and not self.moves:BasicAttackDue(now)then return end
    self.busy=true;self.lastAttack=now;self.attackCount+=1
    self.attackTicket=(self.attackTicket or 0)+1;local ticket=self.attackTicket
    local generation=self.generation;local request={generation=generation,started=now}
    self.attackRequests[ticket]=request
    request.worker=task.spawn(function()
        local began=os.clock()
        local ok,err=pcall(function()
            if self.generation~=generation or self.attackRequests[ticket]~=request then return end
            if self.moves and self.moves.SendBasicAttack then return self.moves:SendBasicAttack()end
            return inputController:FireInput("MouseButton1")
        end)
        self.lastInputRoundTrip=os.clock()-began
        if ok then self.inputReplies=(self.inputReplies or 0)+1;self.lastInputReplyType=typeof(err)
        else self.inputErrors=(self.inputErrors or 0)+1;self.lastInputError=tostring(err)end
        self.attackRequests[ticket]=nil
        if self.generation==generation then self.busy=next(self.attackRequests)~=nil end
        if not ok and self.active and self.generation==generation then
            self.lastError=tostring(err);record("input-error",self.lastError)
        end
    end)
end

local function chooseTarget(ignorePack)
    local folder=living()
    if not folder then return nil end
    local best,bestRoot,bestHumanoid,score
    local candidates={}
    for _,m in ipairs(folder:GetChildren()) do
        if matches(m.Name) and isNPC(m) and(not S.questTarget or m==S.questTarget)and (ignorePack or not S.pack or S.pack.members[m]) and (S.cooldown[m] or 0)<os.clock() then
            local h=m:FindFirstChildOfClass("Humanoid")
            local r=m:FindFirstChild("HumanoidRootPart")
            if r then S.ready[m]=S.ready[m] or os.clock() else S.ready[m]=nil end
            if h and h.Health>0 and r and os.clock()-(S.ready[m] or os.clock())>=0.05 and horizontal(r.Position,S.home.Position)<=S.radius and math.abs(r.Position.Y-S.home.Position.Y)<100 then
                candidates[#candidates+1]={model=m,root=r,health=h}
            end
        end
    end
    for _,candidate in ipairs(candidates)do
        local density=0

        local d=(density>0 and candidate.health.Health*.05 or candidate.health.Health*2)
            +horizontal(candidate.root.Position,S.root.Position)-density*80
        if density>0 then
            d+=math.max(0,horizontal(candidate.root.Position,S.pack.anchor)-S.packCombatRadius)*8
            d+=math.max(0,candidate.root.Position.Y-S.pack.anchor.Y-4)*20
        end
        if not score or d<score then best,bestRoot,bestHumanoid,score=candidate.model,candidate.root,candidate.health,d end
    end
    return best,bestRoot,bestHumanoid
end

function S:HasFarmTarget()
 if not self.root or not self.home then return false end
 return chooseTarget(true)~=nil
end
