function S:ClearHealthRecovery()
    local stale=self.needRecovery or self.phase=="recovering"
    self.needRecovery=false
    if stale then
        self.flightPosition=nil
        if self.phase=="recovering"or self.phase=="returning"then self.phase="waiting"end
    end
end
function S:WaitingPose()
    if self.mobName=="Kuro"then
        local npc=self.questTarget or self.target
        local health=npc and npc.Parent and npc:FindFirstChildOfClass("Humanoid")
        if not health or health.Health<=0 then
            npc=self.bossFarm and self.bossFarm:FindBoss("Kuro")
            health=npc and npc:FindFirstChildOfClass("Humanoid")
        end
        local root=npc and npc.Parent and npc:FindFirstChild("HumanoidRootPart")
        local lift=health and health.Health>0 and root and(self:CombatFarmPosition()=="Down"and -self.downHeight or self.height)or 0
        return CFrame.new(profiles.Kuro.waitingPosition+Vector3.new(0,lift,0))
    end
    local questRoot=self.questTarget and self.questTarget.Parent and self.questTarget:FindFirstChild("HumanoidRootPart")
    if questRoot then return CFrame.new(questRoot.Position+Vector3.new(0,self:CombatFarmPosition()=="Down"and -self.downHeight or self.height,0))end
    if self.questTarget and self.questHoverTarget==self.questTarget and self.questHoverPose then return self.questHoverPose end
    local profile=profiles[self.mobName]
    if profile and profile.waitingPosition and not self.questTarget then return CFrame.new(profile.waitingPosition)end
    return self.home and self.home+Vector3.new(0,self.waitLift or 2,0)
end
function S:HoldMissingQuestTarget()

    if self.loot or(self.pack and self.pack.cleared)then return false end
    local npc=self.questTarget
    if not npc then self.questHoverTarget=nil;self.questHoverPose=nil;return false end
    local targetRoot=npc.Parent and npc:FindFirstChild("HumanoidRootPart")
    local health=npc:FindFirstChildOfClass("Humanoid")
    if self.questHoverTarget~=npc then self.questHoverTarget=npc;self.questHoverPose=nil end
    if targetRoot then
        self.questHoverPose=CFrame.new(targetRoot.Position+Vector3.new(0,self:CombatFarmPosition()=="Down"and -self.downHeight or self.height,0))
        return false
    end
    if health and health.Health<=0 then return false end
    self.questHoverPose=self.questHoverPose or(self.root and self.root.CFrame)
    if self.mobName=="Kuro"then self.questHoverPose=self:WaitingPose()end
    if npc.Name=="Funny Valentine"or npc.Name=="Funny Valentine / The 23rd President"then self.questHoverPose=self:ValentineWaitingPose()end
    if not self.questHoverPose or not self.root or not self.root.Parent then return false end
    self:CancelAttackRequests()
    self.root.Anchored=false;self.root.CFrame=self.questHoverPose
    self.root.AssemblyLinearVelocity=Vector3.zero;self.root.AssemblyAngularVelocity=Vector3.zero
    self.visual=self.questHoverPose
    return true
end
function S:HoldWaiting()
    local pose=self:WaitingPose()
    if pose and self.root and self.root.Parent then
        self.root.Anchored=false;self.root.CFrame=pose;self.root.AssemblyLinearVelocity=Vector3.zero;self.root.AssemblyAngularVelocity=Vector3.zero
    end
end
