function S:ConstrainKuroPosition(position)
    if self.mobName~="Kuro"then return position end
    local center=profiles.Kuro.waitingPosition
    local delta=Vector3.new(position.X-center.X,0,position.Z-center.Z)
    if delta.Magnitude<=30 then return position end
    local edge=center+delta.Unit*30
    return Vector3.new(edge.X,position.Y,edge.Z)
end
function S:HoldKuroOutsideArena()
    if self.mobName~="Kuro"or  (nil)  or self.lifecycleBusy or self.activityOwner or self.loot or(self.pack and self.pack.cleared)then return false end
    if not self.root or not self.root.Parent then return false end
    local npc=self.questTarget or self.target
    local root=npc and npc.Parent and npc:FindFirstChild("HumanoidRootPart")
    local health=npc and npc:FindFirstChildOfClass("Humanoid")
    local center=profiles.Kuro.waitingPosition
    local outside=root and health and health.Health>0 and
        (Vector3.new(root.Position.X-center.X,0,root.Position.Z-center.Z).Magnitude>30 or math.abs(root.Position.Y-center.Y)>15)
    local defensive=self.moves and self.moves.TickKuroM1Guard and self.moves:TickKuroM1Guard()
    if not outside and not defensive then
        if self.moves and self.moves.HoldKuroBlock then self.moves:HoldKuroBlock(false)end
        if self.phase=="kuro-arena-wait"then self.phase="waiting";self.flightPosition=nil end
        return false
    end
    if self.phase~="kuro-arena-wait"then
        self:CancelAttackRequests()
        if self.moves then self.moves:Cancel("Kuro outside arena")end
    end

    if self.moves and self.moves.HoldKuroBlock then self.moves:HoldKuroBlock(true)end
    self.phase="kuro-arena-wait";self.visual=CFrame.new(center);self.flightPosition=nil
    self.lastProgress=os.clock()
    self.root.Anchored=false;self.root.CFrame=self.visual
    self.root.AssemblyLinearVelocity=Vector3.zero;self.root.AssemblyAngularVelocity=Vector3.zero
    return true
end
local function releaseTarget()
    S.ghost=nil;S.target=nil;S.targetRoot=nil;S.targetHumanoid=nil
end
local function curseAttackPosition(position)
    if S.mobName~="Curses"and not(S:CombatFarmPosition()=="Down")then return position end
    local now=os.clock();local cached=S.curseGroundCache
    if not cached or now-cached.time>.2 or math.abs(position.X-cached.x)>4 or math.abs(position.Z-cached.z)>4 then
        local params=RaycastParams.new();params.FilterType=Enum.RaycastFilterType.Include
        local map=workspace:FindFirstChild("Map")
        params.FilterDescendantsInstances=map and{map,workspace.Terrain}or{workspace.Terrain}
        params.IgnoreWater=true
        local hit=workspace:Raycast(position+Vector3.new(0,8,0),Vector3.new(0,-160,0),params)
        if hit and hit.Normal.Y>.5 then
            local root=S.targetRoot;local humanoid=S.targetHumanoid
            local offset=math.clamp((root and root.Size.Y/2 or 1)+(humanoid and humanoid.HipHeight or 2),2.5,6)
            cached={time=now,x=position.X,z=position.Z,y=hit.Position.Y+offset,groundY=hit.Position.Y}
            S.curseGroundCache=cached
        else cached=nil;S.curseGroundCache=nil end
    end
    if not cached then return position end
    return Vector3.new(position.X,math.min(position.Y,(S:CombatFarmPosition()=="Down")and cached.groundY or cached.y),position.Z)
end

local function combatPose(position)
    local orbit= false ;if orbit then return orbit end

    local down=S:CombatFarmPosition()=="Down"
    if down and S.pack then

        local lowest=position.Y
        for member in pairs(S.pack.members or{})do
            local root=member.Parent and member:FindFirstChild("HumanoidRootPart")
            local humanoid=member.Parent and member:FindFirstChildOfClass("Humanoid")
            if root and humanoid and humanoid.Health>0 and horizontal(root.Position,position)<24 then lowest=math.min(lowest,root.Position.Y)end
        end
        position=Vector3.new(position.X,lowest,position.Z)
    end
    position=curseAttackPosition(position)
    local origin=position+Vector3.new(0,S:CombatHeight(),0)

    return CFrame.new(origin)
end
function S:CombatPose(position)return combatPose(position)end

function S:CanStartMimic()
    if self.pauseAfterPack or self.tetherDrain or self.lifecycleBusy or self.loot or self.pack then return false end
    if not self.active then return true end
    return self.phase=="between-packs"or self.phase=="waiting"or self.phase=="off"
end
local function beginNext()
    if (S.pauseAfterPack or S.tetherDrain)and not S.pack then return end
    S.flightPosition=nil


    local m,r,h=chooseTarget()
    if not m and S.pack then
        local alive=false
        for member in pairs(S.pack.members)do
            local health=member.Parent and member:FindFirstChildOfClass("Humanoid")
            local root=member.Parent and member:FindFirstChild("HumanoidRootPart")
            if health and health.Health>0 and root and horizontal(root.Position,S.home.Position)<=S.radius
                and math.abs(root.Position.Y-S.home.Position.Y)<100 then alive=true;break end
        end
        if not alive then

            S.pack.zeroSince=S.pack.zeroSince or os.clock()
            if os.clock()-S.pack.zeroSince<.2 then
                releaseTarget();S.phase="pack-retry";return
            end
            releaseTarget();S.phase="pack-loot";S.pack.cleared=os.clock();S.pack.deadline=os.clock()+6;S.pack.hover=S.visual or CFrame.new(S.pack.center+Vector3.new(0,S.height,0))
            record("pack-cleared",{id=S.pack.id,center=S.pack.center,otherMobsAlive=chooseTarget(true)~=nil})
            return
        end

        S.pack.zeroSince=nil
        releaseTarget();S.phase="pack-retry"
        S.root.CFrame=S.visual or(S.home+Vector3.new(0,S.height,0));S.root.AssemblyLinearVelocity=Vector3.zero;S.root.AssemblyAngularVelocity=Vector3.zero
        return
    end
    if m then
        if S.pack then S.pack.zeroSince=nil end
        if not S.pack then
            S.packSequence=(S.packSequence or 0)+1
            local members={[m]=true};local count=1
            for _,member in ipairs(living():GetChildren())do
                local health=member:FindFirstChildOfClass("Humanoid")
                local root=member:FindFirstChild("HumanoidRootPart")
                if member~=m and matches(member.Name) and isNPC(member) and health and health.Health>0 and root
                    and horizontal(S.npcOrigins[member] or root.Position,S.npcOrigins[m] or r.Position)<=45 and horizontal(root.Position,S.home.Position)<=S.radius then
                    members[member]=true;count+=1
                end
            end
            local existing={}
            for _,obj in ipairs(workspace:GetChildren()) do if obj.Name:lower():find("chest",1,true) then existing[obj]=true end end
            local positions,origins,initialHP={},{},{};for member in pairs(members) do local root=member:FindFirstChild("HumanoidRootPart");if root then positions[member]=root.Position;origins[member]=S.npcOrigins[member] or root.Position;local hp=member:FindFirstChildOfClass("Humanoid");if hp then initialHP[member]=hp.Health end end end
            S.pack={id=S.packSequence,center=r.Position,members=members,positions=positions,spawnPositions=origins,initialHP=initialHP,existingChests=existing,started=os.clock(),anchor=r.Position}
            record("pack-start",{id=S.pack.id,count=count,center=S.pack.center})
        end
        S.target,S.targetRoot,S.targetHumanoid=m,r,h
        S.phase="attacking";S.lastProgress=os.clock();S.lastHP=h.Health;S.hasHit=false
        record("target",{name=m.Name,hp=h.Health})
    else
        releaseTarget();S.phase="returning";record("return",S.home)
    end
end

local function allocateAttack(dt)

    S.statsClock+=dt
    if unloaded or S.statsBusy or S.statsClock<2 then return end
    S.statsClock=0;S.statsBusy=true
    task.spawn(function()
        local ok,err=pcall(function()
            local ability=player.Data.Ability.Value
            local stats=statRemote.GetAbilityStats:InvokeServer(ability)
            if unloaded or player.Data.Ability.Value~=ability then return end
            S.lastStats=stats
            local amount=math.max(0,math.floor(tonumber(stats.StatPoints) or 0))
            if amount==0 then return end
            local applied=statRemote.ApplyStats:InvokeServer(ability,{Attack=amount,Defense=0,Health=0,Special=0})
            if unloaded then return end
            local after=statRemote.GetAbilityStats:InvokeServer(ability)
            S.lastStats=after
            local gained=math.max(0,(after.Stats.Attack or 0)-(stats.Stats.Attack or 0))
            S.statsAllocated+=gained
            record("attack-stats",{amount=gained,result=applied,ability=ability,remaining=after.StatPoints})
        end)
        S.statsBusy=false
        if not ok then S.statsError=tostring(err);record("stats-error",S.statsError) end
    end)
end

local function packAlive(position)
    local folder=living()
    if not folder then return false end
    for _,m in ipairs(folder:GetChildren())do
        if matches(m.Name) and isNPC(m)then
            local h=m:FindFirstChildOfClass("Humanoid")
            local r=m:FindFirstChild("HumanoidRootPart")
            if h and h.Health>0 and r and horizontal(position,r.Position)<60 then return true end
        end
    end
    return false
end
local chestFailures=setmetatable({}, {__mode="k"})
local chestFirstSeen=setmetatable({}, {__mode="k"})
function S:GetChestRarity(chest)
    local rarity=chest:GetAttribute("Rarity")
    local known={Common=true,Rare=true,Epic=true,Legendary=true}
    if type(rarity)=="string"and known[rarity]then return rarity end
    local fromName=chest.Name:match("^(%a+)_Chest$")
    if fromName and known[fromName]then return fromName end
end
function S:IsChestEnabled(chest)
    local rarity=self:GetChestRarity(chest)
    return rarity~=nil and self.chestRarities[rarity]==true
end

function S:ChestCandidates()
    local result={}
    if not self.home then return result end
    for _,chest in ipairs(workspace:GetChildren()) do
        if chest.Name:lower():find("chest",1,true) and self:IsChestEnabled(chest)then
            local root=chest:IsA("BasePart") and chest or chest:FindFirstChild("RootPart")
            local attachment=root and root:FindFirstChild("ProximityAttachment")
            local prompt=attachment and attachment:FindFirstChild("Interaction")
            if root and root:IsA("BasePart") and horizontal(root.Position,self.home.Position)<=self.radius
                and math.abs(root.Position.Y-self.home.Position.Y)<100 then

                chestFirstSeen[chest]=chestFirstSeen[chest] or os.clock()
                table.insert(result,{chest=chest,root=root,prompt=prompt,firstSeen=chestFirstSeen[chest],ready=prompt and prompt:IsA("ProximityPrompt") and prompt.Enabled and prompt.KeyboardKeyCode==Enum.KeyCode.E})
            end
        end
    end
    return result
end
local function beginLoot()
    if not S.collectChests or not S.pack or (not S.pack.cleared and not S.pack.chestBreak) then return false end
    local best,distance
    S.lootPending=0
    local candidates=S:ChestCandidates()

    if S.pack.cleared and not S.pack.chestScope then
        S.pack.chestScope={}
        for _,candidate in ipairs(candidates)do S.pack.chestScope[candidate.chest]=true end
    end
    for _,candidate in ipairs(candidates) do
        local belongs=S.pack.chestScope and S.pack.chestScope[candidate.chest]==true or false
        do
            for _,positions in ipairs({S.pack.positions,S.pack.spawnPositions or {}}) do
                for _,position in pairs(positions) do
                    if horizontal(candidate.root.Position,position)<=30 then belongs=true;break end
                end
                if belongs then break end
            end
        end
        local ready=belongs and (chestRetry[candidate.chest] or 0) or math.huge

        local usable=candidate.ready or os.clock()-(chestFirstSeen[candidate.chest]or os.clock())<.35
        if usable and ready<os.clock()+30 then
            S.lootPending+=1
            if ready<=os.clock() and candidate.ready then
                local d=(candidate.root.Position-S.root.Position).Magnitude
                if not distance or d<distance then best,distance=candidate,d end
            end
        end
    end
    if not best then return false end
    S.pack.lastChest=os.clock()

    local pose=S:InteractionPose(best.prompt,best.root)
    S.pack.lootPose=pose
    S.loot={chest=best.chest,root=best.root,prompt=best.prompt,started=os.clock(),stage="arrive",above=S.pack.hover,pose=pose}
    S.pack.hadAttempt=true;S.phase="looting";S.chestAttempts+=1;S.lootStatus="Opening "..best.chest.Name
    S.root.CFrame=S.loot.pose;S.root.AssemblyLinearVelocity=Vector3.zero
    record("chest-arrive",{name=best.chest.Name,pack=S.pack.id,hold=best.prompt.HoldDuration,range=best.prompt.MaxActivationDistance,poseY=pose.Position.Y,chestY=best.root.Position.Y})
    return true
end

function S:BeginIdleChestLoot()
    if not self.active or not self.collectChests or self.pack or self.loot
        or self.pauseAfterPack or self.tetherDrain or self.lifecycleBusy or self.activityOwner
        or not self.root or not self.home then return false end
    if os.clock()-(self.lastIdleChestScan or 0)<.15 then return false end
    self.lastIdleChestScan=os.clock()
    local priorPhase=self.phase
    self.pack={id=(self.packSequence or 0)+1,center=self.home.Position,members={},positions={},spawnPositions={},
        started=os.clock(),cleared=os.clock(),hover=self.visual or self:WaitingPose(),zoneSweep=true}
    if beginLoot()then
        self.packSequence=self.pack.id
        record("idle-chest-sweep",{id=self.pack.id,pending=self.lootPending});return true
