local function lootTick()
    local loot=S.loot
    if not loot then S.phase="pack-loot";return end
    local age=os.clock()-loot.started

    if not loot.requestedAt and not S:IsChestEnabled(loot.chest)then
        S.root.CFrame=loot.pose;S.root.AssemblyLinearVelocity=Vector3.zero
        S.loot=nil;S.phase="pack-loot";return
    end
    if not S.collectChests then loot.stage="return" end
    if loot.stage=="arrive" then
        S.root.CFrame=loot.pose;S.root.AssemblyLinearVelocity=Vector3.zero
        if not loot.prompt.Parent or not loot.prompt.Enabled then loot.stage="return"
        elseif age>=1/60 then
            loot.requestedAt=os.clock()
            local ok=S:RequestChestPrompt(loot.prompt)
            loot.fired=os.clock();loot.stage="pressed"
            if not ok then loot.stage="return" end
        end
    end
    if loot.stage=="pressed" then
        S.root.CFrame=loot.pose;S.root.AssemblyLinearVelocity=Vector3.zero
        local held=os.clock()-loot.fired

        if not loot.confirmed and loot.prompt.Parent and loot.prompt.Enabled and held<.7 then
            if not S:RequestChestPrompt(loot.prompt)then loot.stage="return"end
        end
        if loot.keyDown and held>=math.max(.06,loot.prompt.HoldDuration+.04) then keyrelease(loot.keyDown);loot.keyDown=nil end
        if loot.confirmed or not loot.prompt.Parent or not loot.prompt.Enabled or held>=.7 then loot.stage="return" end
    end
    if loot.stage=="return" then
        if loot.keyDown then keyrelease(loot.keyDown);loot.keyDown=nil end
        loot.groundSeconds=age;S.root.CFrame=loot.pose;S.root.AssemblyLinearVelocity=Vector3.zero
        loot.stage="confirm";loot.returned=os.clock()
    end
    if loot.stage=="confirm" then
        S.root.CFrame=loot.pose;S.root.AssemblyLinearVelocity=Vector3.zero
        local removed=not loot.chest.Parent or not loot.prompt.Parent

        if loot.confirmed or os.clock()-loot.returned>=2 then
            local confirmed=loot.confirmed==true
            if confirmed or removed then chestFailures[loot.chest]=nil;chestRetry[loot.chest]=os.clock()+120
