            end
            record("chest-finished",{name=loot.chest.Name,confirmed=confirmed,unavailable=removed and not confirmed,groundSeconds=loot.groundSeconds,failures=chestFailures[loot.chest]})
            S.loot=nil;S.phase="pack-loot"
            if S.pack then
                S.pack.lastChest=os.clock()

                if confirmed then
                    S.root.CFrame=loot.pose;S.root.AssemblyLinearVelocity=Vector3.zero
                    if beginLoot()then return end
                    if S.lootPending==0 then

                        if S.pack.chestBreak then
                            S.pack.chestBreak=nil
                            releaseTarget();beginNext()
                        else
                            record("pack-loot-done",{id=S.pack.id,pending=0,attackBusy=S.busy})
                            S.pack=nil;releaseTarget();S.phase="between-packs"
                        end
                        return
                    end
                    S.root.CFrame=S.pack.hover;S.root.AssemblyLinearVelocity=Vector3.zero
                end
            end
        end
    end
end
