    local ok,err=pcall(function()writefile(pendingPath,Http:JSONEncode(env.__UmbrellaFreeInventoryPending or {}))end)
    K.persistenceError=not ok and tostring(err)or nil
end
local function setPending(value)
 value.serverJob=game.JobId;env.__UmbrellaFreeInventoryPending=value;savePending()
 if K.persistenceError then value.state="not-sent";error("Cannot save action journal: "..K.persistenceError)end
end
local function log(kind,data)
    savePending()
    K.events[#K.events+1]={kind=kind,time=os.clock(),data=data}
    if #K.events>100 then table.remove(K.events,1)end
end
local function bag()
    local found={}
    for _,folder in ipairs({p.Backpack,p.Character or p.Backpack})do
        for _,tool in ipairs(folder:GetChildren())do
            if tool:IsA("Tool")and tool:GetAttribute("UUID")and tool:GetAttribute("ItemId")then found[tool:GetAttribute("UUID")]=tool end
        end
    end
    return found
end
function K:SetHold(owner,amounts)
    assert(type(owner)=="string")
    self.holds[owner]=amounts and table.clone(amounts)or nil
    self.protectedIds=nil;self.reserved={};self.knownBag={}
end
function K:ReleaseHold(owner)

    if self.busy or(env.__UmbrellaFreeInventoryPending and env.__UmbrellaFreeInventoryPending.state=="pending")then return false end
    self:SetHold(owner,nil);return true
end
function K:ProtectedItemIds()
    if self.protectedIds then return self.protectedIds end
    local ids={}
    for _,amounts in pairs(self.holds)do for id,n in pairs(amounts)do if n>0 then ids[id]=true end end end
    self.protectedIds=ids;return ids
end
function K:RequiredItemAmount(id)
    local amount=0

    for _,amounts in pairs(self.holds)do amount=math.max(amount,amounts[id]or 0)end
    return amount
end
function K:HasUncertainInventoryAction()
    return self.journalError~=nil or self.busy or(S.items and S.items.deletePending~=nil)or(env.__UmbrellaFreeInventoryPending and env.__UmbrellaFreeInventoryPending.state=="pending")or false
end
function K:IsReserved(tool)
    local id,uuid=tool:GetAttribute("ItemId"),tool:GetAttribute("UUID")
    if self:ProtectedItemIds()[id]or self.reserved[uuid]then return true end
    if not self.knownBag[uuid]then
        for _,amounts in pairs(self.holds)do if(amounts[id]or 0)>0 then return true end end
    end
    return false
end
function K:Snapshot(storedMaxAge)
    local stored=self.storedCache
    if not stored or not storedMaxAge or os.clock()-(self.storedCacheAt or 0)>=storedMaxAge then
        stored=srv.InventoryService.RF.GetItems:InvokeServer("ItemInventory")
        assert(type(stored)=="table","Inventory read unavailable")
        self.storedCache=stored;self.storedCacheAt=os.clock()
    end
    assert(type(stored)=="table","Inventory read unavailable")
    local result={counts={},bag={},stored={},storageCounts={},uuids={}}
    local function add(uuid,id,where)
        if result.uuids[uuid]then return end
        result.uuids[uuid]=id;result.counts[id]=(result.counts[id]or 0)+1
        where[id]=(where[id]or 0)+1
    end
    for key,v in pairs(stored)do
        if type(v)=="table"and v._ItemId then result.storageCounts[v._ItemId]=(result.storageCounts[v._ItemId]or 0)+1 end
        if type(v)=="table"and v._ItemId and not v._Locked then add(v._UUID or key,v._ItemId,result.stored)end
    end
    local tools=bag();local ordered={};for uuid,t in pairs(tools)do ordered[#ordered+1]=uuid;add(uuid,t:GetAttribute("ItemId"),result.bag)end
    table.sort(ordered)
    local quotas={};for _,amounts in pairs(self.holds)do for id,n in pairs(amounts)do quotas[id]=(quotas[id]or 0)+n end end
    for id,n in pairs(quotas)do quotas[id]=math.max(0,n-(result.stored[id]or 0))end
    local reserve,known={},{}
    for _,uuid in ipairs(ordered)do
        known[uuid]=true;local id=tools[uuid]:GetAttribute("ItemId")
        if(quotas[id]or 0)>0 then reserve[uuid]=true;quotas[id]-=1 end
    end
    self.reserved=reserve;self.knownBag=known;self.snapshot=result;self.snapshotAt=os.clock()
    return result
end
function K:FinishFarm(shouldContinue)
    S.pauseAfterPack=true
    local deadline=os.clock()+120
    local ok,reason=pcall(function()
        repeat
            assert(self.alive and(not shouldContinue or shouldContinue()),"Manual farm transition cancelled")
            if not S.activityOwner and not S.loot and(not S.active or not S.pack)then return end
            assert(os.clock()<deadline,"Current pack/loot did not finish; transition stopped")
            task.wait(.03)
        until false
    end)
    S.pauseAfterPack=nil
    if not ok then error(reason)end
    S:Stop("Inventory pack and loot complete")
end
function K:InvalidateQuestReads(id)
    for _,entry in pairs(self.questReads or{})do if entry.id==id then entry.at=nil end end
end
function K:ReadQuestField(id,field,fresh)
    self.questReads=self.questReads or{}
    local key=id..":"..field;local entry=self.questReads[key]
    if not entry then entry={id=id,field=field};self.questReads[key]=entry end
    entry.used=os.clock()
    fresh=fresh or self.busy or(env.__UmbrellaFreeInventoryPending and env.__UmbrellaFreeInventoryPending.state=="pending")
    local due=os.clock()+10
    while entry.reading do assert(self.alive~=false and os.clock()<due,"Quest read pending");task.wait(.05)end
    if not fresh and entry.at and os.clock()-entry.at<(self.questRequestInterval or 1) then return entry.value end
    if not fresh and entry.error and os.clock()-(entry.attemptAt or 0)<(self.questRequestInterval or 1) then error(entry.error)end
    assert(self.alive~=false,"Quest reader unloaded")
    entry.reading=true;entry.attemptAt=os.clock()
    local ok,value=pcall(function()return srv.QuestLineService.RF[field]:InvokeServer(id)end)
    entry.reading=false
    if not ok then entry.at=nil;entry.error=tostring(value);error(value)end
    assert(self.alive~=false,"Quest reader unloaded")
    entry.value=value;entry.at=os.clock();entry.error=nil
    return value
end
function K:QuestState(id,localOnly,fresh)

    local info
    if not localOnly then info=self:ReadQuestField(id,"GetQuestlineInfo",fresh)end
    local result={id=id,info=info,tasks={},active=false}
    for _,folder in ipairs(p.QuestLines:GetChildren())do
        if folder:GetAttribute("InternalName")==id then
            result.active=true
            for _,v in ipairs(folder:GetDescendants())do
                if v:IsA("ValueBase")and not v:GetAttribute("Reward")then
                    result.tasks[#result.tasks+1]={name=v.Name,value=v.Value,max=v:GetAttribute("MaxValue")}
                end
            end
        end
    end
    return result
end
local function operation(name,fn)
    assert(K.alive and not K.busy and not K.journalError,"Inventory operation blocked: "..tostring(K.journalError or "busy"))
    local pending=env.__UmbrellaFreeInventoryPending
    assert(not pending or pending.state~="pending","Uncertain previous operation; reconcile before retry")
    K.busy=true
    local ok,result=pcall(fn)
    K.busy=false
    if not ok then log("error",{operation=name,error=tostring(result)});error(result)end
    savePending()
    if type(result)=="table"and(result.confirmed==true or(tonumber(result.stored)or 0)>0)then K.receiptSerial=(K.receiptSerial or 0)+1 end
    return result
end
local function quietAction(name,fn,forceReset,shouldContinue,allowCombat,stayHere)
    return operation(name,function()
        if stayHere then
            assert(S.lifecycle:Clean(),"Wait for clean character; no reset permitted")
            assert(not shouldContinue or shouldContinue(),"Action cancelled")
            K.actionToken=S.generation
            local ok,result=pcall(fn);K.actionToken=nil
            if not ok then error(result)end
            return result
        end
        return S.lifecycle:WithCleanCharacter(name,function(token)
            K.actionToken=token
            local ok,result=pcall(fn);K.actionToken=nil
            if not ok then error(result)end
            return result
        end,{forceReset=forceReset==true,waitForClean=forceReset~=true,allowCombat=allowCombat==true,maintenance=allowCombat~=true,shouldContinue=shouldContinue})
    end)
end
function K:QuestDialogue(id,argument)
 self:InvalidateQuestReads(id)
 local result=table.pack(pcall(function()
  if argument==nil then return srv.DialogueService.RF.CheckDialogue:InvokeServer(id)end
  return srv.DialogueService.RF.CheckDialogue:InvokeServer(id,argument)
 end))
 self:InvalidateQuestReads(id)
 if not result[1]then error(result[2],0)end
 return table.unpack(result,2,result.n)
end
local function questReady(id,q)
    return q.active or(q.info and q.info.Completed~=true)or false
end
function K:AwaitQuestReady(id,shouldContinue)
    local deadline=os.clock()+8;local q
    repeat
        assert(self.alive and(not shouldContinue or shouldContinue()),"Quest acceptance cancelled")
        q=self:QuestState(id)
        if questReady(id,q)then return q,true end
        task.wait(.1)
    until os.clock()>=deadline
    return q,false
end
local function acceptQuest(id,shouldContinue)
    assert(K.alive and(not shouldContinue or shouldContinue()),"Quest acceptance cancelled")
    local replicated=K:QuestState(id,true)
    if replicated.active and #replicated.tasks>0 then return {status="existing",quest=replicated}end
    return quietAction("accept-adventure",function()
        local current=K:QuestState(id)
        if current.active or(current.info and current.info.Completed~=true)then
            local after,ready=K:AwaitQuestReady(id,shouldContinue)
            return {status=ready and "existing"or "replication-pending",quest=after}
        end
        local available=srv.AdventureService.RF.GetQuests:InvokeServer()
        if type(available)~="table"then return {status="cooldown-or-unavailable"}end

        if not available[id]and id~="Save_The_Village_Adventure"then return {status="cooldown-or-unavailable"}end
        if not srv.DialogueService.RF.CheckRequirement:InvokeServer("AdventureCondition",id,1)then return {status="occupied"}end

        assert(K.alive and(not shouldContinue or shouldContinue())and S.generation==K.actionToken,"Quest acceptance cancelled")
        setPending({state="pending",operation="accept",id=id,time=os.clock()})
        local sentAt=os.clock();local combatAtSend=p.Character and p.Character:GetAttribute("InCombat")==true
        local reply=K:QuestDialogue(id)
        local after,ready
        if reply==false then after=K:QuestState(id);ready=questReady(id,after)
        else after,ready=K:AwaitQuestReady(id,shouldContinue)end
        if ready then env.__UmbrellaFreeInventoryPending.state="confirmed"
        elseif reply==false or type(reply)=="string"then env.__UmbrellaFreeInventoryPending.state="rejected"end
        log("quest-accept",{id=id,reply=reply,confirmed=ready,combatAtSend=combatAtSend,seconds=os.clock()-sentAt})
        local state=env.__UmbrellaFreeInventoryPending.state
        return {status=state=="pending"and "replication-pending"or state,quest=after,reply=reply}
    end,false,shouldContinue,true)
end
function K:AcceptAdventure(id,shouldContinue)
    assert(id=="Zoros_Swords_Adventure"or id=="Save_The_Village_Adventure","Unsupported adventure")
    return acceptQuest(id,shouldContinue)
end
function K:ClearConflictingSlayer(wanted,shouldContinue)
    local function check()
        assert(self.alive and(not shouldContinue or shouldContinue()),"Slayer replacement cancelled")
        assert(not(S.lifecycle and S.lifecycle:BossAlive()),"Finish live boss before replacing Slayer contract")
    end
    local function current()
        local q=self:QuestState("Slayer_Quest",false,true)
        assert(type(q.info)=="table"and type(q.info.Metadata)=="table","Slayer metadata unavailable")
        local metadata=q.info.Metadata
        if metadata.Slayer then return metadata.Slayer end
        for key in pairs(metadata)do
            local name=type(key)=="string"and key:match("^%[(.-)%] Slayer XP$")
            if name then return name end
        end
        assert(type(metadata.Slayers)=="table"and not q.info.Completed
            and(q.info.Step==nil or q.info.Step==1)and #(q.tasks or{})==0,"Slayer contract state unavailable")
        return nil
    end
    check()
    assert(not self.ReconcilePending or self:ReconcilePending(),"Previous Slayer mutation awaits receipt")
    local name=current()
    if not name or name==wanted then return {status="ready"}end
    return quietAction("discard-slayer",function()
        check();local before=current()
        if not before or before==wanted then return {status="ready"}end
        local pending={state="pending",operation="discard-slayer",id="Slayer_Quest",slayer=before,wanted=wanted,time=os.clock()}
        check();setPending(pending);check()
        local reply=srv.QuestLineService.RF.DiscardQuestline:InvokeServer("Slayer_Quest")
        local deadline=os.clock()+8
        repeat
            check();local after=current()
            if not after or after==wanted then pending.state="confirmed";savePending();return {status="ready"}end
            if reply==false then pending.state="rejected";savePending();return {status="rejected"}end
            task.wait(.1)
        until os.clock()>=deadline
        savePending();return {status="replication-pending"}
    end,false,shouldContinue,true)
end
function K:ReserveRecipes(owner,recipeIds,extras)
    local amounts=table.clone(extras or {})
    local recipes=ItemData.GetCraftingRecipes()
    for _,recipeId in ipairs(recipeIds)do
        local recipe=assert(recipes[recipeId],"Recipe unavailable: "..recipeId)
        for _,side in ipairs({recipe.Input,recipe.Output})do
            for id,n in pairs(side.Items or {})do amounts[id]=math.max(amounts[id]or 0,n)end
        end
    end
    self:SetHold(owner,amounts)
end
local function withdrawStored(self,id,shouldContinue,exactUUID)
        local stored=srv.InventoryService.RF.GetItems:InvokeServer("ItemInventory")
        local uuid
        for key,item in pairs(stored)do if item._ItemId==id and not item._Locked and(not exactUUID or(item._UUID or key)==exactUUID)then uuid=item._UUID or key;break end end
        assert(uuid,"Stored item missing: "..id)
        assert(self.alive and(not shouldContinue or shouldContinue()),"Withdrawal cancelled")
        setPending({state="pending",operation="withdraw",uuid=uuid,time=os.clock()})

        require(game.ReplicatedStorage.ReplicatedModules.KnitPackage.Knit).GetService("InventoryService").ItemInventory:Fire({ItemId=id,UUID=uuid})
        local deadline=os.clock()+5;local confirmed=false
        repeat
            assert(self.alive and(not shouldContinue or shouldContinue()),"Withdrawal cancelled after send; receipt pending")
            local current=srv.InventoryService.RF.GetItems:InvokeServer("ItemInventory")
            confirmed=bag()[uuid]~=nil and current[uuid]==nil
            if not confirmed then task.wait(.05)end
        until confirmed or os.clock()>deadline or not self.alive
        if confirmed then env.__UmbrellaFreeInventoryPending.state="confirmed"end
        log("withdraw",{id=id,uuid=uuid,confirmed=confirmed})
        if not confirmed then
            local current=srv.InventoryService.RF.GetItems:InvokeServer("ItemInventory")
            if current[uuid]and not bag()[uuid]then

                env.__UmbrellaFreeInventoryPending.state="not-withdrawn";savePending()
                return {confirmed=false,status="retry",uuid=uuid}
            end
        end
        return {confirmed=confirmed,uuid=uuid}
end
function K:WithdrawItem(id,shouldContinue)
 assert(id=="ITEM_78"or id=="ITEM_542"or id=="ITEM_3"or id=="ITEM_91"or id=="ITEM_1","Unsupported manual summon supply")
 return quietAction("withdraw",function()return withdrawStored(self,id,shouldContinue)end,false,shouldContinue)
end
function K:AbilityCatalog()
    local owned=srv.InventoryService.RF.GetItems:InvokeServer("AbilityInventory")
    assert(type(owned)=="table","Ability inventory unavailable")
    local list,counts={},{}
    for uuid,item in pairs(owned)do
        if item._ItemType=="Ability"and type(item._ItemId)=="string"then
            local name=item._DisplayName or item._ItemId
            counts[name]=(counts[name]or 0)+1
            list[#list+1]={uuid=uuid,id=item._ItemId,abilityId=item._AbilityId or tonumber(item._ItemId:match("ABILITY_(%d+)")),name=name,item=item}
        end
    end
    table.sort(list,function(a,b)if a.name~=b.name then return a.name<b.name end;return a.uuid<b.uuid end)
    local used={}
    for _,v in ipairs(list)do
        local suffix=counts[v.name]>1 and(" ["..v.uuid:sub(-12).."]")or ""
        v.label=v.name..suffix
        if used[v.label]then v.label=v.name.." ["..v.uuid.."]"end
        used[v.label]=true
    end
    return list,owned
end
function K:EquipAbility(uuid,shouldContinue,preparedCharacter)
    assert(not shouldContinue or shouldContinue(),"Ability switch cancelled")
    if p.Data.Ability:GetAttribute("UUID")==uuid then return {confirmed=true,uuid=uuid,unchanged=true}end
    assert(not preparedCharacter or(p.Character==preparedCharacter and S.lifecycle:Clean()),"Prepared ability switch character changed")
    return quietAction("equip-farming-ability",function()
        assert(type(uuid)=="string"and uuid~="","Select a farming ability")
        assert(not p:GetAttribute("InventoryDisabled"),"Inventory disabled")
        local before=srv.InventoryService.RF.GetItems:InvokeServer("AbilityInventory")
        local item=assert(before[uuid],"Selected farming ability is no longer owned")
        assert(item._ItemType=="Ability","Selected item is not an ability")
        if p.Data.Ability:GetAttribute("UUID")==uuid then return {confirmed=true,uuid=uuid,unchanged=true}end
        assert(self.alive and S.generation==self.actionToken and(not shouldContinue or shouldContinue()),"Ability switch cancelled")
        assert(not preparedCharacter or p.Character==preparedCharacter,"Prepared ability switch character changed")
        setPending({state="pending",operation="equip-ability",uuid=uuid,time=os.clock()})
        local deadline=os.clock()+10;local nextRequest=0
        repeat
            assert(self.alive and S.generation==self.actionToken,"Ability switch cancelled")
            if os.clock()>=nextRequest then
                assert(not shouldContinue or shouldContinue(),"Ability switch cancelled")
                srv.InventoryService.RE.AbilityInventory:FireServer({ItemId=item._ItemId,UUID=uuid,Equip=true});nextRequest=os.clock()+.5
            end
            task.wait(.05)
        until p.Data.Ability:GetAttribute("UUID")==uuid or os.clock()>deadline or not self.alive
        assert(p.Data.Ability:GetAttribute("UUID")==uuid,"Selected ability equip unconfirmed")
        local after=srv.InventoryService.RF.GetItems:InvokeServer("AbilityInventory")
        for key in pairs(before)do assert(after[key],"Ability inventory changed unexpectedly")end
        env.__UmbrellaFreeInventoryPending.state="confirmed";savePending();log("ability-equipped",{uuid=uuid})
        return {confirmed=true,uuid=uuid}
    end,preparedCharacter==nil,shouldContinue)
end
function K:ReconcilePending()
 if self.journalError then return false end
 local j=env.__UmbrellaFreeInventoryPending
 if not j or j.state~="pending"then return true end
 if (j.operation=="equip-ability"or j.operation=="equip-standless")and p.Data.Ability:GetAttribute("UUID")==j.uuid then j.state="confirmed";savePending();return true end
 if j.operation=="withdraw"and bag()[j.uuid]then local stored=srv.InventoryService.RF.GetItems:InvokeServer("ItemInventory");if stored[j.uuid]==nil then j.state="confirmed";savePending();return true end end
 return false
end
function K:Unload() self.alive=false end
local loaded,loadError=pcall(function()
 if isfile(pendingPath)then
  local j=Http:JSONDecode(readfile(pendingPath));assert(type(j)=="table","Invalid inventory journal")
  if next(j)then assert(type(j.state)=="string"and type(j.operation)=="string","Invalid inventory action journal")end
  env.__UmbrellaFreeInventoryPending=j
 end
end)
if not loaded then K.journalError=tostring(loadError)end
return K

end)() end
do local value=(function()
--!nocheck
local S=assert(getgenv().UmbrellaFree)
local env=getgenv()
local p=game.Players.LocalPlayer

local L={alive=true,busy=false,busoReset=false,formReset=false,status="Ready",events={},requests={},connections={}}
S.lifecycle=L
local saved=env.__UmbrellaFreeLifecycleReloadSettings
if saved and  true   then L.busoReset=saved.busoReset==true;L.formReset=false end
env.__UmbrellaFreeLifecycleReloadSettings=nil
local function log(kind,data)
    L.events[#L.events+1]={time=os.clock(),kind=kind,data=data}
    if #L.events>120 then table.remove(L.events,1)end
    if kind=="reset-request"or kind=="reset-blocked"then

        local ok,err=pcall(function()
            local H=game:GetService("HttpService");local path="UmbrellaFree/"..p.UserId.."-reset-audit.json"
            local rows={}
            if isfile(path)then local raw=readfile(path);if #raw<250000 then rows=H:JSONDecode(raw)end end
            local tools={};local c=p.Character
            for _,box in pairs({p.Backpack,c})do if box then for _,t in ipairs(box:GetChildren())do
                if t:IsA("Tool")then tools[#tools+1]={id=t:GetAttribute("ItemId"),uuid=t:GetAttribute("UUID"),name=t.Name}end
            end end end
            local pending=env.__UmbrellaFreeInventoryPending
            rows[#rows+1]={at=os.time(),job=game.JobId,kind=kind,data=data,tools=tools,
                radiation=c and c:GetAttribute("SpaceRadiation"),ability=p.Data.Ability:GetAttribute("UUID"),

                pending=pending and{operation=pending.operation,state=pending.state},
                storageSnapshotAt=S.inventoryOps and S.inventoryOps.snapshotAt,
                stored=S.inventoryOps and S.inventoryOps.snapshot and S.inventoryOps.snapshot.stored}
            while #rows>16 do table.remove(rows,1)end
            writefile(path,H:JSONEncode(rows))
        end)
        L.resetAuditError=not ok and tostring(err)or nil
    end
end
function L:Check(token)
    assert(self.alive and S.generation==token,"Reset/action cancelled")
end
function L:Clean()
    local c=p.Character;local h=c and c:FindFirstChildOfClass("Humanoid")
    return c and h and h.Health>0 and c:FindFirstChild("HumanoidRootPart")
        and not c:GetAttribute("InCombat")and not p:GetAttribute("InCombat")and not p:GetAttribute("InventoryDisabled")
end
function L:AwaitClean(token,previous)
    self.waitingForCharacter=previous
    local deadline=os.clock()+25
    repeat
        self:Check(token)
        if self:Clean()and(not previous or p.Character~=previous)then self.waitingForCharacter=nil;return p.Character end
        task.wait(.03)
    until os.clock()>deadline
    error("Respawn/clean character not confirmed")
end
function L:Flush(token)
    self:Check(token)
    if S.items and S.items.autoStore then S.items:StoreReady(token)end
    self:Check(token)
    if S.misc and S.misc.autoRecycle then
        local previousBusy=S.misc.busy;S.misc.busy=true
        local ok,err=pcall(function()S.misc:DrainRecycle(function()self:Check(token)end)end)
        S.misc.busy=previousBusy
        if not ok then error(err)end
    end
end
function L:BossAlive()
 if S.bossEncounter then return true end
 local target=S.questTarget
 local h=target and target.Parent and target:FindFirstChildOfClass("Humanoid")
 return h and h.Health>0 or false
end

function L:CosmosResetBlocked()
 local c=p.Character
 if c and c.GetAttribute and type(c:GetAttribute("SpaceRadiation"))=="number" then return true end
 local r=S.resources and S.resources.current
 if r and r.requested and not r.received then return true end
 local ids={ITEM_909=true,ITEM_910=true,ITEM_911=true,ITEM_914=true,ITEM_915=true,ITEM_916=true,ITEM_917=true,ITEM_925=true,ITEM_912=true,ITEM_913=true,ITEM_918=true,ITEM_919=true,ITEM_920=true,ITEM_921=true,ITEM_922=true}
 for _,box in pairs({p.Backpack,c})do
  if box and box.GetChildren then for _,tool in ipairs(box:GetChildren())do
   if tool:IsA("Tool")then
    local id=tool:GetAttribute("ItemId")

    if ids[id]then return true end
   end
  end end
 end
 return false
end

function L:WithCleanCharacter(reason,fn,options)
    options=options or{}

    while self:BossAlive()or self.busy or S.lifecycleBusy or(not options.miscOwner and S.misc and S.misc.busy)or(S.statRoll and S.statRoll.actionBusy)or(S.traits and S.traits.actionBusy)do
        assert(not options.shouldContinue or options.shouldContinue(),"Lifecycle action cancelled")
        assert(self.alive,"Lifecycle unloaded");if self:BossAlive()then self.status="Waiting for boss fight before character maintenance"end;task.wait(.03)
    end
    assert(self.alive,"Lifecycle unloaded")
    assert(not options.shouldContinue or options.shouldContinue(),"Lifecycle action cancelled")
