local LegacyInput=Knit.GetService("MoveInputService")

local LegacyInputRemote=rs.ReplicatedModules.KnitPackage.Knit.Services.MoveInputService.RF.FireInput

local Stats=require(rs.ReplicatedModules.StatsHandler)

local States=require(rs.ReplicatedModules.StateHandler)

local NativeMoves=require(rs.ReplicatedRoot.Services.Gameplay.MoveService)

local NativeInput=require(rs.ReplicatedRoot.Services.MoveInputController)

local M={alive=true,autoMoves=false,autoInputs=false,autoQTE=false,autoJC=false,

    selectedMoves={},selectedInputs={},pendingNamed={},events={},retry={},localCooldown={},catalog={},cursor=0,

    status="Ready",jcStatus="Waiting for Vergil verification",connections={},settingsVersion=0}

S.moves=M

M.namedOptions={"Hollow Nuke","Stance Switch","Summon","Busoshoku Haki","Kenbunshoku Haki","Haoshoku Haki","SDT","Doppelganger"}

M.inputOptions={"MouseButton1","MouseButton2","Q","E","R","T","Y","U","G","J","Z","X","V","B","H"}

for _,key in ipairs({"Q","E","R","T","Y","U","G","J","Z","X","V","B","H"})do M.inputOptions[#M.inputOptions+1]=key.."+"end

local tracker

for _,v in pairs(debug.getupvalues(Controller.Input))do

    if type(v)=="table"and type(v.AddKey)=="function"and type(v.RemoveKey)=="function"then tracker=v;break end

end

local function record(kind,data)

    M.events[#M.events+1]={kind=kind,time=os.clock(),info=data}

    if #M.events>160 then table.remove(M.events,1)end

end

local function connect(signal,fn)local c=signal:Connect(fn) M.connections[#M.connections+1]=c;return c end

local function identity()

    local a=player.Data.Ability

    return tostring(a:GetAttribute("UUID"))..":"..tostring(a:GetAttribute("AbilityLevel"))..":"..tostring(a:GetAttribute("AscensionRank"))

end

function M:Export()

    return {autoMoves=self.autoMoves,autoInputs=self.autoInputs,autoQTE=self.autoQTE,autoJC=self.autoJC,

        selectedMoves=table.clone(self.selectedMoves),selectedInputs=table.clone(self.selectedInputs)}

end

function M:InvalidateCatalog()

    self.catalogRevision=(self.catalogRevision or 0)+1

    self.catalogIdentity=nil;self.nextRefresh=0

end

function M:Restore(t)

    if not t then return end

    for _,key in ipairs({"autoMoves","autoInputs","autoQTE","autoJC"})do self[key]=t[key]==true end

    for _,key in ipairs({"selectedMoves","selectedInputs"})do if type(t[key])=="table"then self[key]=table.clone(t[key])end end

    self:Changed()

end

function M:Changed()self.settingsVersion+=1;self:Cancel("Settings changed") self:InvalidateCatalog()end

function M:SelectedForCombat(entry)

    return(self.autoInputs and self.selectedInputs[entry.input])or(self.autoMoves and self.selectedMoves[entry.name])or false

end

function M:UseNamedOnce(name,owner)

    if self.alive then

        self.pendingNamed[name]=player.Data.Ability:GetAttribute("UUID")

        self.pendingNamedOwners=self.pendingNamedOwners or{};self.pendingNamedOwners[name]=owner

    end

end

function M:ClearOwnedNamed(owner)

    for name,source in pairs(self.pendingNamedOwners or{})do

        if source==owner then self.pendingNamed[name]=nil;self.pendingNamedOwners[name]=nil end

    end

end

function M:Refresh()

    if self.refreshing or os.clock()<(self.nextRefresh or 0)then return end

    self.refreshing=true;self.nextRefresh=os.clock()+1

    local revision=self.catalogRevision or 0

    local stamp=identity();local a=player.Data.Ability.Value;local sourceUUID=player.Data.Ability:GetAttribute("UUID");local sourceCharacter=player.Character

    self.refreshWorker=task.spawn(function()

        local ok,result=pcall(function()

            if not Controller:IsLegacyMoveset()then

                local catalog={}

                for _,move in ipairs(NativeMoves.FindMoves(player.Character,{Bound=true}))do

                    for _,binding in pairs(move.Binds or{})do

                        local flag=binding.Flag

                        if type(flag)=="string"then

                            catalog[#catalog+1]={name=move.Name,input=flag:upper(),stats=move.Data or{},unlocked=true,modern=move}

                        end

                    end

                end

                table.sort(catalog,function(x,y)return x.name<y.name end)

                return catalog

            end

            local packet=MoveService:GetMovesInfo(a):expect()

            local equipped=Controller:GetEquippedMoves()

            local ability=Stats.GetStats(player.Data.Ability:GetAttribute("AbilityName"),player.Data.Skin:GetAttribute("SkinName"))

            local sub=Stats.GetStats("SubPowers")

            local info=Controller:GetMoveset().MovesInfo or{}

            local catalog={}

            for name,binding in pairs(equipped)do

                local data=info[name]or(sub and sub.Moveset and sub.Moveset.MovesInfo and sub.Moveset.MovesInfo[name])or{}

                local st=ability and ability.Stats[name]or sub and sub.Stats[name]

                if binding.Keybind and st then

                    local key=binding.Keybind:upper()

                    if binding.Held and key:sub(-1)~="+"then key..="+"end

                    catalog[#catalog+1]={name=name,input=key,stats=st,info=data,state=binding.State,priority=binding.Priority or 0,airborne=binding.Airborne,

                        unlocked=data.Unlocked==true or(packet.UnlockedMoves and packet.UnlockedMoves[name]==true)

                            or(data.Equipped==true and data.MoveCapCount==false)}

                end

            end

            table.sort(catalog,function(x,y)return x.name<y.name end)

            return catalog

        end)

        if self.alive and revision==(self.catalogRevision or 0)and stamp==identity()and sourceCharacter==player.Character then

            if ok and #result>0 then self.catalog=result;self.catalogIdentity=stamp;self.catalogUUID=sourceUUID;self.catalogCharacter=sourceCharacter;self.catalogAt=os.clock();self.status="Ready"

            elseif ok then self.catalogIdentity=nil;self.status="Waiting for native moveset"

            else self.status="Move data unavailable";self.lastError=tostring(result);record("catalog-error",self.lastError)end

        end

        self.refreshing=false;self.refreshWorker=nil

    end)

end

local function objectFor(key,state)

    local base=key:gsub("%+$","")

    local mouse=base:upper():match("^MOUSEBUTTON([12])$")

    return {KeyCode=mouse and Enum.KeyCode.Unknown or Enum.KeyCode[base:upper()],

        UserInputType=mouse and Enum.UserInputType["MouseButton"..mouse]or Enum.UserInputType.Keyboard,

        UserInputState=state or Enum.UserInputState.Begin,Held=key:sub(-1)=="+"}

end

function M:Release(action)

    if not action or action.released then return end

    action.released=true

    if action.modern then

        pcall(NativeInput.HandleInput,{Input=objectFor(action.input,Enum.UserInputState.End),GameProcessed=false})

    else

        pcall(function()Controller:Input(objectFor(action.base),"Ended")end)

        if tracker then tracker:RemoveKey(action.base)end

        Controller.Inputs[action.base]=nil;Controller.Inputs[action.base.."+"]=nil

    end

end

function M:ReleaseBasicAttack()

    if self.basicAttack then self:Release(self.basicAttack);self.basicAttack=nil end

end

function M:DirectCombatActive()

    if not self.alive or not Controller:IsLegacyMoveset()then return false end

    if S.phase=="mimic"then

        local c=S.mimic and S.mimic.current

        return c and c.stage=="fight"and S.activityOwner=="mimic"and c.lease and c.lease.generation==S.generation or false

    end

    return S.active and(S.phase=="attacking")or false

end

function M:BasicAttackDue(now)

    return not self:DirectCombatActive()or now>=(self.nextDirectM1 or 0)

end

function M:CancelDirectRequests()

    local current=coroutine.running()

    for _,request in pairs(self.directRequests or{})do

        if request.thread and request.thread~=current then pcall(task.cancel,request.thread)end

    end

    self.directRequests={};self.nextDirectM1=nil

end

function M:DirectCombatTick(character)

    if not self:Safe(character,true)then return end

    self.directRequests=self.directRequests or{};self.directRetry=self.directRetry or{}

    local now=os.clock();local uuid=player.Data.Ability:GetAttribute("UUID")

    for input,request in pairs(self.directRequests)do

        if request.uuid~=uuid or request.character~=character or request.generation~=S.generation or now-request.started>3 then

            if request.thread then pcall(task.cancel,request.thread)end

            self.directRequests[input]=nil

        end

    end

    local used={}

    for _,entry in ipairs(self.catalog)do

        local input=entry.input

        local selected=self:SelectedForCombat(entry)

        if selected and input~="MOUSEBUTTON1"and input~="MOUSEBUTTON2"and entry.name~="Summon"and entry.name~="Busoshoku Haki"

            and not self.pendingNamed[entry.name]and not used[input]and not self.directRequests[input]

            and now>=(self.directRetry[input]or 0)and self:Eligible(entry,character,true)then

            used[input]=true;self.directRetry[input]=now+.115

            local request={uuid=uuid,character=character,generation=S.generation,started=now,name=entry.name}

            self.directRequests[input]=request

            request.thread=task.spawn(function()

                local ok,reply=pcall(function()

                    if not self.alive or player.Character~=character or player.Data.Ability:GetAttribute("UUID")~=uuid

                        or self.directRequests[input]~=request or S.generation~=request.generation

                        or not self:DirectCombatActive()or not self:Safe(character,true)then return end

                    return LegacyInputRemote:InvokeServer(buffer.fromstring("\0"..input))

                end)

                if self.directRequests[input]==request then self.directRequests[input]=nil end

                if not ok then self.lastError=tostring(reply);record("native-input-error",{name=entry.name,error=tostring(reply)})

                else record("native-input",{name=entry.name,input=input,replyType=typeof(reply)})end

            end)

        end

    end

end

local kuroM1Animations={

    ["14324703321"]="Flash Dash",

    ["17358403773"]="Shakushi",

    ["17364050315"]="Unpredictable Speeds",

}

function M:HoldKuroBlock(on)

    local character=player.Character

    local uuid=player.Data.Ability:GetAttribute("UUID")

    local guard=self.kuroBlock

    if guard and(not on or guard.character~=character or guard.uuid~=uuid)then self.kuroBlock=nil;self:Release(guard);guard=nil end

    if not on or not character then return end

    if not guard then

        guard={base="F",input="F",character=character,uuid=uuid,modern=not Controller:IsLegacyMoveset()}

        self.kuroBlock=guard;self.kuroBlockRetry=0

    end

    if character:GetAttribute("Blocking")~=true and os.clock()>=(self.kuroBlockRetry or 0)then

        self.kuroBlockRetry=os.clock()+.1

        local ok,err=pcall(function()

            if guard.modern then NativeInput.HandleInput({Input=objectFor("F"),GameProcessed=false})

            elseif not guard.pressed then Controller:Input(objectFor("F"),"Began");guard.pressed=true

            else Controller:FireInput("F")end

        end)

        if not ok then self.lastError=tostring(err)end

    end

end

function M:EndKuroGuard()

    self:HoldKuroBlock(false)

    local g=self.kuroGuard;self.kuroGuard=nil;self.kuroM1Paused=nil

    if not g then return end

    for _,c in ipairs(g.connections)do c:Disconnect()end

    for _,c in ipairs(g.humanoidConnections or{})do c:Disconnect()end

end

function M:TickKuroM1Guard()

    local npc=self.alive and S.active and  true   and not S.loot and not S.lifecycleBusy

        and not S.activityOwner and(S.phase=="attacking"or S.phase=="waiting"or S.phase=="kuro-arena-wait")

        and(S.questTarget or S.target)

    local own=player.Character

    local ownHum=npc and own and own:FindFirstChildOfClass("Humanoid")

    if not npc or not npc.Parent or(npc.Name~="Kuro"and npc.Name~="Kuro of a Hundred Plans")

        or not ownHum or ownHum.Health<=0 then self:EndKuroGuard();return false end

    local h=npc:FindFirstChildOfClass("Humanoid")

    if h and h.Health<=0 then

        if self.kuroGuard then record("kuro-native-death",{hp=h.Health,bar=npc:GetAttribute("BAR")})end

        self:EndKuroGuard();return false

    end

    local g=self.kuroGuard

    if g and(g.npc~=npc or g.character~=own or g.generation~=S.generation)then self:EndKuroGuard();g=nil end

    if not g then

        g={npc=npc,character=own,generation=S.generation,connections={}};self.kuroGuard=g

        local function changed()

            if self.kuroGuard~=g or g.callback then return end

            g.callback=true

            local ok,err=pcall(function()

                self:TickKuroM1Guard()

                if self.kuroM1Paused and S.HoldKuroOutsideArena then S:HoldKuroOutsideArena()end

            end)

            g.callback=nil

            if not ok then self.lastError=tostring(err);record("kuro-guard-error",tostring(err))end

        end

        g.changed=changed

        g.connections[#g.connections+1]=npc.AttributeChanged:Connect(changed)

        g.connections[#g.connections+1]=npc.ChildAdded:Connect(changed)

        g.connections[#g.connections+1]=npc.ChildRemoved:Connect(changed)

        g.connections[#g.connections+1]=npc.AncestryChanged:Connect(changed)

    end

    if g.humanoid~=h then

        for _,c in ipairs(g.humanoidConnections or{})do c:Disconnect()end

        g.humanoid=h;g.humanoidConnections={}

        if h then

            g.humanoidConnections[#g.humanoidConnections+1]=h.HealthChanged:Connect(g.changed)

            g.humanoidConnections[#g.humanoidConnections+1]=h.AnimationPlayed:Connect(g.changed)

        end

    end

    local root=npc:FindFirstChild("HumanoidRootPart")

    local bar,max=npc:GetAttribute("BAR"),npc:GetAttribute("MaxBAR")

    local danger

    if not h or not root then danger="Replication/root unavailable"

    elseif type(bar)=="number"and type(max)=="number"and max>0 and bar>=max then danger="BAR full"

    elseif npc:FindFirstChild("CustomHighlight")then danger="BAR highlight"

    elseif npc:GetAttribute("MoveActive")==true then danger="Kuro action"

    else

        for _,track in ipairs(h:GetPlayingAnimationTracks())do

            local id=tostring(track.Animation and track.Animation.AnimationId):match("%d+$")

            if track.IsPlaying and kuroM1Animations[id]then danger=kuroM1Animations[id];break end

        end

    end

    if g.reason~=danger then

        record("kuro-native-phase",{reason=danger or"ready",hp=h and h.Health,bar=bar,maxBar=max,rootY=root and root.Position.Y})

        g.reason=danger

    end

    if danger then

        if not self.kuroM1Paused then

            self.kuroM1Paused=true

            self:Cancel("Kuro defensive window")

            if S.CancelAttackRequests then S:CancelAttackRequests()end

        else self:ReleaseBasicAttack()end

        self.status="Kuro: "..danger

    elseif self.kuroM1Paused then

        self.kuroM1Paused=nil;record("kuro-m1-resume",{})

    end

    if not danger then self:HoldKuroBlock(false)end

    return danger~=nil

end

function M:SendBasicAttack()

    if self:TickKuroM1Guard()then return false end

    if self:DirectCombatActive()then

        self:ReleaseBasicAttack();self.nextDirectM1=os.clock()+.25

        return LegacyInputRemote:InvokeServer(buffer.fromstring("\0MouseButton1"),true)

    end

    local character=player.Character;local uuid=player.Data.Ability:GetAttribute("UUID")

    local modern=not Controller:IsLegacyMoveset()

    local a=self.basicAttack

    if a and(a.character~=character or a.uuid~=uuid or a.modern~=modern)then self:ReleaseBasicAttack();a=nil end

    if not a then

        a={input="MouseButton1",base="MouseButton1",modern=modern,character=character,uuid=uuid}

        self.basicAttack=a

        if not modern then

            if tracker then tracker:AddKey(a.base)end

            Controller.Inputs[a.base]=true

        end

    end

    if modern then

        return NativeInput.HandleInput({Input=objectFor(a.input),GameProcessed=false})

    end

    LegacyInput:FireRawInput(a.base)

    return Controller:FireInput(a.input)

end

function M:Cancel(reason)

    if self.EndGolemGuard then self:EndGolemGuard()end

    if self.EndWindGuard then self:EndWindGuard()end

    self:ReleaseBasicAttack()

    self:CancelDirectRequests()

    local a=self.action

    if a then self:Release(a);self.action=nil;record("cancel",{name=a.name,reason=reason})end

end

function M:EndGolemGuard()

    local a=self.golemAttack;self.golemAttack=nil;self.golemPose=nil

    if a and a.guard then self:Release(a.guard)end

end

function M:TickGolemGuard()

    local npc=S.target;local character=player.Character

    local h=npc and npc.Parent and npc:FindFirstChildOfClass("Humanoid")

    local own=character and character:FindFirstChildOfClass("Humanoid")

    local root=npc and npc.Parent and npc:FindFirstChild("HumanoidRootPart")

    if not self.alive or not S.active or S.mobName~="Camellite Golems"or S.phase~="attacking"

        or not npc or npc.Name~="Camellite Golem"or not h or h.Health<=0 or not root

        or not own or own.Health<=0 or S.lifecycleBusy or S.activityOwner

        or(S.items and S.items.tetherSuspended)then self:EndGolemGuard();return false end

    local uuid=player.Data.Ability:GetAttribute("UUID")

    local a=self.golemAttack

    if a and(a.npc~=npc or a.character~=character or a.generation~=S.generation or a.uuid~=uuid)then self:EndGolemGuard();a=nil end

    local track,danger

    for _,tr in ipairs(h:GetPlayingAnimationTracks())do

        local id=tostring(tr.Animation and tr.Animation.AnimationId):match("%d+$")

        if tr.IsPlaying then

            if id=="133307155795797"then track=tr end

            if id=="112677356448656"or id=="96632119110038"then danger=tr end

        end

    end

    if danger or(a and a.mode=="evade"and os.clock()<a.untilTime)then

        if not a or a.mode~="evade"then

            self:Cancel("Golem slam evasion")

            if S.CancelAttackRequests then S:CancelAttackRequests()end

            a={npc=npc,character=character,generation=S.generation,uuid=uuid,mode="evade"}

            self.golemAttack=a

        end

        if danger then a.untilTime=os.clock()+.6 end

        local height=S:CombatFarmPosition()=="Down"and -25 or 45

        self.golemPose=CFrame.new(root.Position+Vector3.new(0,height,0))

        if S.root and S.root.Parent then S.root.CFrame=self.golemPose;S.root.AssemblyLinearVelocity=Vector3.zero;S.root.AssemblyAngularVelocity=Vector3.zero end

        self.status="Evading Golem slam";return true

    end

    if a and a.mode=="evade"then self:EndGolemGuard();a=nil end

    if npc:GetAttribute("Vulnerable")==true or npc:GetAttribute("PerfectBlocked")==true then self:EndGolemGuard();return false end

    if not track then self:EndGolemGuard();return false end

    self.golemAttempts=self.golemAttempts or setmetatable({},{__mode="k"})

    local t=track.TimePosition

    local speed=math.max(.1,tonumber(track.Speed)or 1.35)

    local pressTime=2.82-speed*.20

    local approachTime=pressTime-speed*.25

    if t>=3.65 or(t>=3.0 and(not a or a.track~=track))or(self.golemAttempts[track]and(not a or a.track~=track))then self:EndGolemGuard();return false end

    if not a or a.track~=track then

        self:Cancel("Golem Sledgehammer windup")

        if S.CancelAttackRequests then S:CancelAttackRequests()end

        a={npc=npc,character=character,generation=S.generation,uuid=uuid,track=track}

        self.golemAttack=a

    end

    if a.pressedAt and os.clock()-a.pressedAt>=.8 then self:EndGolemGuard();return false end

    self.golemPose=nil

    if t>=approachTime then

        local facing=root.CFrame.LookVector;facing=Vector3.new(facing.X,0,facing.Z)

        facing=facing.Magnitude>.1 and facing.Unit or Vector3.new(0,0,-1)

        local position=root.Position+facing*7

        self.golemPose=CFrame.lookAt(position,root.Position)

        if S.root and S.root.Parent then S.root.CFrame=self.golemPose;S.root.AssemblyLinearVelocity=Vector3.zero;S.root.AssemblyAngularVelocity=Vector3.zero end

    end

    if t>=pressTime and not a.guard then

        self.golemAttempts[track]=true;a.pressedAt=os.clock()

        a.guard={base="F",input="F",character=character,uuid=uuid,modern=not Controller:IsLegacyMoveset()}

        local ok,err=pcall(function()

            if a.guard.modern then NativeInput.HandleInput({Input=objectFor("F"),GameProcessed=false})

            else Controller:Input(objectFor("F"),"Began")end

        end)

        if not ok then self.lastError=tostring(err);self:EndGolemGuard();return true end

        record("golem-parry-begin",{animationTime=t})

    end

    self.status=self.golemPose and"Parrying Golem Sledgehammer"or"Waiting above/below Golem Sledgehammer"

    return true

end

function M:GolemDefensePose()

    self:TickGolemGuard()

    return self.golemPose

end

local windAnimations={['14187677670']=true,['17653523069']=true,['18259005607']=true}

function M:EndWindGuard()

    local guard=self.windGuard;if not guard then return end

    self.windGuard=nil;self:Release(guard);record("wind-block-end",{})

end

function M:WindBlockRequested()

    local npc=S.active and(S.questTarget or S.target)

    if not npc or npc.Name~="Kars"or not npc.Parent then

        if self.windConnection then self.windConnection:Disconnect();self.windConnection=nil end

        self.windNPC=nil;self.windTracks=nil;self.windUntil=nil;return false

    end

    local h=npc:FindFirstChildOfClass("Humanoid")

    if not h or h.Health<=0 then return false end

    if self.windNPC~=npc then

        if self.windConnection then self.windConnection:Disconnect()end

        self.windNPC=npc;self.windTracks={};self.windUntil=0

        self.windConnection=h.AnimationPlayed:Connect(function(track)

            local id=tostring(track.Animation and track.Animation.AnimationId):match("%d+$")

            if windAnimations[id]then

                self.windTracks[track]=true;self.windUntil=os.clock()+.4

                self:TickWindGuard()

            end

        end)

    end

    for _,track in ipairs(h:GetPlayingAnimationTracks())do

        local id=tostring(track.Animation and track.Animation.AnimationId):match("%d+$")

        if windAnimations[id]and track.IsPlaying then self.windTracks[track]=true end

    end

    for track in pairs(self.windTracks)do

        if track.IsPlaying then self.windUntil=os.clock()+.4 else self.windTracks[track]=nil end

    end

    return os.clock()<(self.windUntil or 0)

end

function M:TickWindGuard()

    if not self:WindBlockRequested()then self:EndWindGuard();return false end

    local character=player.Character;local hum=character and character:FindFirstChildOfClass("Humanoid")

    if not hum or hum.Health<=0 or S.lifecycleBusy then self:EndWindGuard();return false end

    local uuid=player.Data.Ability:GetAttribute("UUID")

    if self.windGuard and(self.windGuard.character~=character or self.windGuard.uuid~=uuid)then self:EndWindGuard()end

    if not self.windGuard then

        self:Cancel("Kars wind defence")

        if S.CancelAttackRequests then S:CancelAttackRequests()end

        self.windGuard={base="F",input="F",character=character,uuid=uuid,modern=not Controller:IsLegacyMoveset()}

        self.windRetry=0;record("wind-block-begin",{})

    end

    local guard=self.windGuard

    if character:GetAttribute("Blocking")~=true and os.clock()>=(self.windRetry or 0)then

        self.windRetry=os.clock()+.1

        local ok,err=pcall(function()

            if guard.modern then NativeInput.HandleInput({Input=objectFor("F"),GameProcessed=false})

            elseif not guard.pressed then Controller:Input(objectFor("F"),"Began");guard.pressed=true

            else Controller:FireInput("F")end

        end)

        if not ok then self.lastError=tostring(err)end

    end

    self.status="Blocking Kars wind";return true

end

function M:Safe(character,utility)

    if self.TickKuroM1Guard and self:TickKuroM1Guard()then return false end

    if self.golemAttack then return false end

    if self.windGuard then return false end

    local hum=character and character:FindFirstChildOfClass("Humanoid")

    local mimic=S.mimic and S.mimic.current

    local mimicFight=mimic and mimic.stage=="fight"and S.phase=="mimic"and S.activityOwner=="mimic"

        and mimic.lease and mimic.lease.generation==S.generation

    if not hum or hum.Health<=0 or Input:GetFocusedTextBox()or S.lifecycleBusy or(S.activityOwner and not mimicFight)or S.loot then return false end

    if mimic then return mimicFight==true end

    return true

end

local function cooldown(name)

    for _,container in ipairs({player,player.Character})do

        local folder=container and container:FindFirstChild("Cooldowns")

        if folder and folder:FindFirstChild(name)then return folder[name]end

    end

    return nil

end

function M:LegacyBindingActive(entry,character)

    local moveState=States.IsStateActive(character,entry.name.."_Move")

    if moveState==false then return false end

    return not entry.state or States.IsStateActive(character,entry.state)==true or moveState==true

end

function M:BindingPriority(entry,character)

    return(entry.state and States.GetStatePriority(character,entry.state))or entry.priority or 0

end

function M:Eligible(entry,character,ignoreMoveActive)

    if entry.modern then

        local valid=entry.modern:Validate()

        if valid and valid.Success==true then return true end

        return false,"Native conditions"

    end

    local winner,priority

    local humanoid=character:FindFirstChildOfClass("Humanoid")

    for _,other in ipairs(self.catalog)do

        if other.input==entry.input then

            local air=other.airborne and humanoid and humanoid.FloorMaterial==Enum.Material.Air

            if self:LegacyBindingActive(other,character)and(not other.airborne or air)then

                local score=self:BindingPriority(other,character)+(air and 10000 or 0)

                if not priority or score>priority then winner=other;priority=score end

            end

        end

    end

    if winner and winner~=entry then return false,"Other move bound in current state"end

    if not entry.unlocked then return false,"Locked"end

    local st=entry.stats

    local cd=st.Cooldown;local cdName=type(cd)=="table"and cd.Name or entry.name

    cdName=cdName or entry.name

    if cooldown(cdName)or os.clock()<(self.localCooldown[cdName]or 0)or os.clock()<(self.retry[entry.name]or 0)then return false,"Cooldown"end

    if character:GetAttribute("Stunned")or(not ignoreMoveActive and(character:GetAttribute("MoveActive")or(entry.input~="MOUSEBUTTON1"and character:GetAttribute("LMBActive"))))then return false,"Busy"end

    if not self:LegacyBindingActive(entry,character)then return false,"State"end

    if entry.name=="Busoshoku Haki"and character:GetAttribute("Busoshoku")~=nil then return false,"Already active"end

    if entry.name=="Summon"then

        if Collection:HasTag(character,"Summoned")then return false,"Already summoned"end

    end

    if entry.name=="SDT"and character:GetAttribute("SDT")then return false,"Already active"end

    local meter=st.Meter

    if meter and(type(meter.RequiredAmount)=="number"or type(meter.RequiredLevel)=="number")then

        local bypass=false

        if type(meter.BypassCheck)=="function"then local ok,v=pcall(meter.BypassCheck,{Character=character,Player=player,Arguments={}}) bypass=ok and v==true end

        if not bypass then

            local cost=table.clone(meter)

            if type(cost.RequiredLevel)=="number"then

                cost.RequiredMeter=math.max(cost.RequiredMeter or cost.RequiredAmount or 0,Combat.GetMeterFromLevel(character,cost.RequiredLevel))

                cost.RequiredLevel=nil

            end

            local result=Combat.ValidateMeter(character,cost)

            if not result or result.Success~=true then return false,"Waiting for HT"end

        end

    end

    return true

end

function M:ShouldPrioritizeMove()

    if not self.alive then return false end

    local character=player.Character

    if not character or not self:Safe(character,true)then return false end

    local a=self.action

    if a then

        if a.input=="MOUSEBUTTON1"or a.character~=character or a.uuid~=player.Data.Ability:GetAttribute("UUID")then return false end

        if character:GetAttribute("MoveActive")==true or os.clock()-a.started<.2 then return true end

        if not a.observed and not a.observedCooldown then return false end

    end

    if not(self.autoMoves or self.autoInputs or next(self.pendingNamed)or  false )then return false end

    if self.catalogCharacter~=character or self.catalogUUID~=player.Data.Ability:GetAttribute("UUID")or self.catalogIdentity~=identity()then return false end

    local direct=self.DirectCombatActive and self:DirectCombatActive()

    for _,entry in ipairs(self.catalog)do

        local selected=self:SelectedForCombat(entry)

            or self.pendingNamed[entry.name]==player.Data.Ability:GetAttribute("UUID")

        local serial=not direct or entry.name=="Summon"or entry.name=="Busoshoku Haki"or self.pendingNamed[entry.name]

        if selected and serial and entry.input~="MOUSEBUTTON1"and self:Eligible(entry,character,true)then return true end

    end

    return false

end

function M:Finish(a,acknowledged)

    self:Release(a)

    local cd=a.stats.Cooldown;local name=type(cd)=="table"and cd.Name or a.name;name=name or a.name

    local native=cooldown(name)

    local manual=type(cd)=="table"and cd.Manual==true

    if acknowledged and not manual and not native and not a.observedCooldown and not a.character:GetAttribute("URF")and not a.character:GetAttribute("TrueURF")then

        local duration=type(cd)=="table"and cd.Time or cd

        if type(duration)=="number"then self.localCooldown[name]=(type(cd)=="table"and cd.AfterMove and os.clock()or a.started)+duration end

    end

    self.retry[a.name]=os.clock()+(manual and not native and not a.observedCooldown and .75 or acknowledged and 0 or .5)

    record("finished",{name=a.name,input=a.input,acknowledged=acknowledged,seconds=os.clock()-a.started,nativeCooldown=native~=nil})

    self.action=nil

end

function M:Start(entry)

    if self.TickKuroM1Guard and self:TickKuroM1Guard()then return false end

    self:ReleaseBasicAttack()

    if entry.input~="MOUSEBUTTON1"and S.attackRequests and next(S.attackRequests)then

