function M:OnFarmStart()

    local wanted=(self.autoMoves and self.selectedMoves["Busoshoku Haki"])or(S.lifecycle and S.lifecycle.busoReset)

    for _,entry in ipairs(self.catalog)do if entry.name=="Busoshoku Haki"and self.autoInputs and self.selectedInputs[entry.input]then wanted=true end end

    if not wanted then return end

    local c=player.Character

