function M:Tick()

    if not self.alive then return false end

    if self.TickKuroM1Guard and self:TickKuroM1Guard()then return true end

    if self.TickGolemGuard and self:TickGolemGuard()then return true end

    if self.TickWindGuard and self:TickWindGuard()then return true end

    local a=self.action

    if a then

        if a.character~=player.Character or a.generation~=S.generation or a.uuid~=player.Data.Ability:GetAttribute("UUID")or a.settingsVersion~=self.settingsVersion

            or not self:Safe(a.character,a.utility)then self:Cancel("Owner or phase changed");return false end

        if not a.modern and a.entry and not self:LegacyBindingActive(a.entry,a.character)then

            self:Cancel("Move form ended");self:InvalidateCatalog();return false

        end

        local active=a.character:GetAttribute("MoveActive")==true

        if a.input=="MOUSEBUTTON1"then active=active or a.character:GetAttribute("LMBActive")==true end

        local summon=a.name=="Summon"

        local summonReady=summon and type(a.desiredSummoned)=="boolean"and Collection:HasTag(a.character,"Summoned")==a.desiredSummoned

        if summon then a.observed=summonReady

        elseif active or(a.input=="MOUSEBUTTON1"and a.character:GetAttribute("LMBActive"))then a.observed=true end

        local cd=a.stats.Cooldown;local cdName=type(cd)=="table"and cd.Name or a.name;cdName=cdName or a.name

        local nativeCooldown=cooldown(cdName)

        if nativeCooldown then a.observedCooldown=true end

        local acknowledged=summon and summonReady or not summon and(a.observed or nativeCooldown)

        if not active and acknowledged then self:Release(a)end

        if not active and a.released and acknowledged then self:Finish(a,true);return false end

        if not a.observed and os.clock()-a.started>1.5 then self:Finish(a,false);return false end

        if os.clock()-a.started>30 then self:Finish(a,a.observed);record("timeout",a.name);return false end

        return true

    end

    if not(self.autoMoves or self.autoInputs or next(self.pendingNamed)or  false )then return false end

    local character=player.Character

    local currentUUID=player.Data.Ability:GetAttribute("UUID")

    if  character  and self.catalogUUID==currentUUID and not Collection:HasTag(character,"Summoned")and self:Safe(character,true)then

        for _,entry in ipairs(self.catalog)do

            local wanted=(self.autoMoves and self.selectedMoves.Summon)or self.pendingNamed.Summon==currentUUID

                or(self.autoInputs and self.selectedInputs[entry.input])

            if entry.name=="Summon"and wanted and(not entry.modern or self.catalogCharacter==character)then

                if self:Eligible(entry,character)and self:Start(entry)then

                    self.pendingNamed.Summon=nil;self.action.utility=true;return true

                end

                break

            end

        end

    end

    local stale=self.catalogIdentity~=identity()or self.catalogCharacter~=character

    if stale or os.clock()-(self.catalogAt or 0)>=3 then self:Refresh()end

    if stale then return false end

    local priorityHaki=(self.pendingNamed["Busoshoku Haki"]==player.Data.Ability:GetAttribute("UUID"))

        or(S.active and self.autoMoves and self.selectedMoves["Busoshoku Haki"])

    if priorityHaki and self:Safe(character,true)then

        for _,entry in ipairs(self.catalog)do

            if entry.name=="Busoshoku Haki"then

                local ready=self:Eligible(entry,character)

                if ready and self:Start(entry)then

                    self.pendingNamed[entry.name]=nil;self.farmStartHaki=nil;self.action.utility=true;return true

                end

                break

            end

        end

    end

    self.farmStartHaki=nil

    local direct=self.DirectCombatActive and self:DirectCombatActive()

    if direct then self:DirectCombatTick(character)end

    for offset=1,#self.catalog do

        local index=(self.cursor+offset-1)%#self.catalog+1

        local entry=self.catalog[index]

        local named=(self.autoMoves and self.selectedMoves[entry.name])or(self.pendingNamed[entry.name]==player.Data.Ability:GetAttribute("UUID"))

        local selected=self.autoInputs and self.selectedInputs[entry.input]

        if direct then

            named=self.pendingNamed[entry.name]==player.Data.Ability:GetAttribute("UUID")

            selected=false

        end

        if(named or selected)and not(S.active and entry.input=="MOUSEBUTTON1")and self:Safe(character,named)then

            local ok,reason=self:Eligible(entry,character)

            if ok then self.cursor=index;if self:Start(entry)then self.pendingNamed[entry.name]=nil;self.action.utility=named;return true end

            else self.status=reason end

        end

    end

    return false

end

local function findQTE(value,depth,seen)

    if depth>3 or seen[value]then return end;seen[value]=true

    if type(value)=="table"and type(rawget(value,"TryHitKey"))=="function"and type(rawget(value,"UpdatePromptRing"))=="function"then return value end

    if type(value)=="function"then for _,v in pairs(debug.getupvalues(value))do if type(v)=="table"or type(v)=="function"then local found=findQTE(v,depth+1,seen) if found then return found end end end end

    return nil

end

