function M:WatchStates(character)

    for _,connection in ipairs(self.stateConnections or{})do connection:Disconnect()end

    self.stateConnections={}

    local function watch(signal,fn)local c=signal:Connect(fn) self.stateConnections[#self.stateConnections+1]=c end

    local function changed()if self.alive then self:InvalidateCatalog()end end

    local function bind(folder)

