    end

    if not character then return end

    local folder=character:FindFirstChild("StatesFolder");if folder then bind(folder)end

    watch(character.ChildAdded,function(child)if child.Name=="StatesFolder"then bind(child) changed()end end)

    watch(character.ChildRemoved,function(child)if child.Name=="StatesFolder"then changed()end end)

end

