  if type(index)=="number"and type(card)=="table"and type(card.Trait)=="string"then ordered[#ordered+1]={index=index,card=card}end
 end
 table.sort(ordered,function(a,b)return a.index<b.index end)
 local parts={};local colors={Common="#AAAAAA",Rare="#3E92FF",Epic="#AF5AFF",Legendary="#FF964B",Mythic="#FF5500"}
