local function validHand(hand)
 if type(hand)~="table"then return false end
 local count=0
 for i,card in pairs(hand)do if type(i)~="number"or type(card)~="table"or type(card.Trait)~="string"or not handler.GetTraitData(card.Trait)then return false end;count+=1 end
