end
function T:RecoverHand()
 local ui=p.PlayerGui.UI.Gameplay
 if not ui.TraitHandPrompt.Visible and not ui.TraitHands.Visible then return end
 for _,c in ipairs(getconnections(ui.TraitHandPrompt.MouseButton1Click))do
  if c.Function and debug.info(c.Function,"s"):match("TraitHands%.UI_TraitHands$")then
   for _,v in pairs(debug.getupvalues(c.Function))do if validHand(v)then return {uuid=uuid(),cards=v}end end
  end
 end

 local cards={}
 for _,card in ipairs(ui.TraitHands.Holder:GetChildren())do
  local index=tonumber(card.Name)
  if index and card:IsA("GuiButton")then
   for _,connection in ipairs(getconnections(card.MouseButton1Click))do
    if connection.Function and debug.info(connection.Function,"s"):match("TraitHands%.UI_TraitHands$")then
     for _,value in pairs(debug.getupvalues(connection.Function))do
      if type(value)=="table"and type(value.Trait)=="string"and handler.GetTraitData(value.Trait)then cards[index]=value end
     end
    end
   end
  end
 end
