local function processHand(self,discardOnly)
 local hand=self.hand;if not hand then return false end
 self:Check();assert(hand.uuid==uuid(),"Ability changed with a pending Trait Hand")
 local best,score
 for i,card in pairs(hand.cards)do
  if not discardOnly and self:Matches(card)then
   local d=handler.GetTraitData(card.Trait);local rank=({Epic=3,Legendary=4,Mythic=5})[d.Rarity]or 0
   local s=rank+(card.Hexed and .5 or 0)
   if not score or s>score or(s==score and i<best)then best=i;score=s end
  end
 end
 if not discardOnly then self.lastRolled=hand.cards end
 self.pending={uuid=hand.uuid,operation=best and "pick"or "discard",index=best,job=game.JobId,trait=best and hand.cards[best]or nil}
 self:Save();self:Check()

 local reply
 if best then reply=service.RF.PickTrait:InvokeServer(best)else reply=service.RF.DiscardTraits:InvokeServer()end
 assert(reply~=false and type(reply)~="string","Trait request rejected: "..tostring(reply))
 self:Check()
 if best then
  local limit=os.clock()+5;local confirmed
  repeat
   self:Check();assert(uuid()==hand.uuid,"Trait confirmation ability changed")
   confirmed=service.RF.GetCurrentTraitInfo:InvokeServer()
   if confirmed and key(confirmed)==key(hand.cards[best])then break end
   task.wait(.05)
  until os.clock()>limit
  assert(confirmed and key(confirmed)==key(hand.cards[best]),"Trait receipt unconfirmed; no retry sent")
  self:RecordChoice(hand.uuid,confirmed,hand.cards)
  self.chosenDisplay={uuid=hand.uuid,trait={Trait=confirmed.Trait,Hexed=confirmed.Hexed==true}}
  if S.webhooks then pcall(S.webhooks.TraitPicked,S.webhooks,hand.uuid,confirmed,hand.cards)end
 end
