local p=game.Players.LocalPlayer
local rs=game.ReplicatedStorage
local Inventory=require(rs.ReplicatedModules.KnitPackage.Knit).GetService("InventoryService")
local C={}
local function persist(status,data,owner)if owner then owner:RecordBossAction(status,data)end end
function C:SetStage(stage)self.stage=stage end
