function C:RecoverNavigation()

 local lease=self.navigationLease

 if not lease or not self.navigationPose or S.activityOwner or S.lifecycleBusy or(S.lifecycle and S.lifecycle.busy)then return end

 if not S.root or not S.root.Parent or S.character~=p.Character or not S.humanoid or S.humanoid.Health<=0 then return end

 local fresh=S:AcquireActivity(self.activityKey or "boss")

 if fresh then

  for key,value in pairs(fresh)do lease[key]=value end

 end

end
function C:RefreshCharacter()

 local deadline=os.clock()+15

 repeat

  self:Check();local character=p.Character

  local root=character and character:FindFirstChild("HumanoidRootPart")

  local h=character and character:FindFirstChildOfClass("Humanoid")

  if root and h and h.Health>0 then S.character=character;S.root=root;S.humanoid=h;return end

  task.wait(.05)

 until os.clock()>deadline

 error("Boss character has not respawned")

end
function C:CancelStream()

 local request=self.streamRequest;self.streamRequest=nil

 if request and request.thread and not request.done then pcall(task.cancel,request.thread)end

end
function C:StreamAround(position,timeout)

 self:Check()

 if self.streamRequest and not self.streamRequest.done then return false end

 local request={done=false};self.streamRequest=request

 request.thread=task.spawn(function()

  request.ok=pcall(function()p:RequestStreamAroundAsync(position,timeout)end)

  request.done=true

 end)

 local deadline=os.clock()+timeout

 while not request.done and os.clock()<deadline do self:Check();task.wait(.05)end

 return request.done and request.ok

end
function C:CombatProfileFor(id,boss)

 local inputs=({[666]={Y=true},[1010]={E=true,G=true},[1600]={E=true,G=true},[1700]={E=true}})[id]

 if not inputs then

  local owned=self.ownedControls and self.ownedControls.moveInputSelection

  inputs=table.clone(owned and owned.before or(S.moves and S.moves.selectedInputs)or{})

 end

 if id==1700 and boss=="Funny Valentine"then inputs.E=nil end

 local h=S.humanoid

 if id~=666 and h and h.Health<(h.MaxHealth or h.Health)*.75 then inputs.Y=true end

 return inputs

end
function C:FindBoss(boss)

 local best,distance

 for _,npc in ipairs(workspace.Living:GetChildren())do

  if npc.Name==boss or(boss=="Dio"and npc.Name=="Hold up, aint you Dio?")or(boss=="Diavolo"and npc.Name=="Diavolo, The Boss")

   or(boss=="Funny Valentine"and npc.Name=="Funny Valentine / The 23rd President")then

   local root=npc:FindFirstChild("HumanoidRootPart");local h=npc:FindFirstChildOfClass("Humanoid")

   if root and h and h.Health>0 then

    local own=p.Character and p.Character:FindFirstChild("HumanoidRootPart")

    local d=own and(root.Position-own.Position).Magnitude or 0

    if not distance or d<distance then best=npc;distance=d end

   end

  end

 end

 return best

end
function C:CollectArrows(amount)

 self:FinishFarm()

 if(K:Snapshot(2).counts.ITEM_1 or 0)>=amount then return end

 local resource=S.resources;local selected=resource.selected

 resource:SetSelected("Meteors");self:SetStage("arrows")

 local ok,err=pcall(function()

  resource:SetEnabled(true,true)

  local progressAt=os.clock();local visits=resource.visits or 0;local lastCount=-1

  while true do

   self:Check();local snapshot=K:Snapshot(2)

   local count=snapshot.counts.ITEM_1 or 0

   if count>=amount then return end

   if count~=lastCount then lastCount=count;progressAt=os.clock();visits=resource.visits or 0 end

   persist("summon-arrows",{value=snapshot.counts.ITEM_1 or 0,required=amount,resource=resource.status},self)

   task.wait(.1)

  end

