 self:PrepareArrowStorage(amount)

 local snapshot=K:Snapshot();local missing=math.max(0,amount-(snapshot.stored.ITEM_1 or 0))

 if missing==0 then return end

 local alreadyStored=Inventory:GetItems("ItemInventory"):expect()

 local tools,uuids={},{}

 for _,box in ipairs({p.Backpack,p.Character})do

  for _,tool in ipairs(box:GetChildren())do

   local uuid=tool:GetAttribute("UUID")

   if missing>0 and tool:IsA("Tool")and tool:GetAttribute("ItemId")=="ITEM_1"and uuid and not alreadyStored[uuid]and not uuids[uuid]then

    tools[#tools+1]=tool;uuids[uuid]=true;missing-=1

   end

