  self.pending.replyType=type(reply);self.pending.reply=tostring(reply)

  persist("store-arrows-awaiting-receipt",{count=#tools,attempt=attempt,replyType=type(reply),reply=tostring(reply)},self)

  local deadline=os.clock()+8

  repeat

   self:Check();local owned=Inventory:GetItems("ItemInventory"):expect();local all=true

   for uuid in pairs(uuids)do if not owned[uuid]then all=false end end

   if all then self.pending=nil;K.storedCache=nil;persist("store-arrows-confirmed",{count=#tools},self);return true end

   task.wait(.1)

  until os.clock()>deadline

  return false

