  self:Check();self.navigationPose=pose;S.root.CFrame=pose;S.root.AssemblyLinearVelocity=Vector3.zero

  self:StreamAround(pose.Position,2)

  self:Check();return action(lease)

 end)

 self.navigationPose=nil;self.navigationLease=nil;self.navigationStationary=nil

 if S.root and S.root.Parent then lease.pose=S.root.CFrame end

 S:ReleaseActivity(lease)

 if not ok then error(result)end

 return result

end
function C:DomainAltar(alternate)

 local domain=alternate and Vector3.new(-980.1797,-129.6053,519.8755)or Vector3.new(27305.60742,-204.70905,12822.94922)

 if not alternate and(S.root.Position-domain).Magnitude>1500 then

  self:AtPose(CFrame.new(-539.78076,-.50313,969.08783),function()

   local deadline=os.clock()+15;local gate

   repeat

    self:Check();local folder=workspace.Map:FindFirstChild("Teleports")

    gate=folder and folder:FindFirstChild("DomainTeleport")

    if gate then break end

    task.wait(.05)

   until os.clock()>deadline

   assert(gate,"Domain entry has not streamed in")

   local prompt=assert(gate:FindFirstChildWhichIsA("ProximityPrompt",true),"Domain entry prompt unavailable")

   local hold=prompt.HoldDuration;prompt.HoldDuration=0

   local ok,err=pcall(fireproximityprompt,prompt);prompt.HoldDuration=hold

   assert(ok,err)

   self.navigationPose=nil

   repeat self:Check();if(S.root.Position-domain).Magnitude<1500 then return end;task.wait(.05)until os.clock()>deadline

   error("Domain entry unconfirmed")

  end)

 end

 return self:AtPose(CFrame.new(domain+Vector3.new(0,4,0)),function()

  local deadline=os.clock()+15

  repeat

   self:Check()

   for _,obj in ipairs(workspace.NPCSpawns:GetDescendants())do

    if obj:IsA("ProximityPrompt")and obj.ObjectText=="Spawn Boss"and obj.Parent:IsA("BasePart")and(obj.Parent.Position-domain).Magnitude<100 then return obj.Parent end

   end

   task.wait(.05)

  until os.clock()>deadline

  error("Domain boss altar has not streamed in")

 end)

end
function C:TrySummonBoss(boss,alternate)

 assert(boss=="Dio"or boss=="Diavolo","Unverified summon recipe")

 assert(not self.pending,"Previous Boss operation is unresolved")

 local data=rs.Remotes.NpcFunc:InvokeServer("Get Boss Data")

 local recipe=assert(type(data)=="table"and data[boss],"Native boss requirements unavailable")

 if recipe.Items then

  for id,amount in pairs(recipe.Items)do

   assert(id=="ITEM_1"and amount<=5,"Unverified summon ingredient")

   self:CollectArrows(amount);self:StoreSummonArrows(amount)

