 repeat

  self:Check()

  for _,npc in ipairs(workspace.Living:GetChildren())do

   if npc.Name==boss or(boss=="Dio"and npc.Name=="Hold up, aint you Dio?")or(boss=="Diavolo"and npc.Name=="Diavolo, The Boss")then

    local root=npc:FindFirstChild("HumanoidRootPart");local h=npc:FindFirstChildOfClass("Humanoid")

