 while S.lifecycle and S.lifecycle.manualResetInFlight do task.wait(.05);assert(self:Continue(),"Boss farm cancelled")end
 local c=p.Character;local r=c and c:FindFirstChild("HumanoidRootPart");local h=c and c:FindFirstChildOfClass("Humanoid")
 if r and h and h.Health>0 then S.character=c;S.root=r;S.humanoid=h end
 self:RecoverNavigation()
end
function B:IsControlLocked(key)return self.running and self.controlLocks and self.controlLocks[key]or false end
for _,name in ipairs({"SetStage","ReleaseControls","RefreshCharacter","StreamAround","CancelStream","RecoverNavigation","CollectArrows","StoreArrowQuota","StoreSummonArrows","AtPose","DomainAltar","TrySummonBoss","CombatProfileFor"})do B[name]=assert(T[name],name)end
function B:FindBoss(name)
 local natural=self.natural[name]
 if natural then
  for _,npc in ipairs(workspace.Living:GetChildren())do
   if npc.Name==natural.nativeName and not game.Players:GetPlayerFromCharacter(npc)then
    local h=npc:FindFirstChildOfClass("Humanoid")
    if h and h.Health>0 and npc:FindFirstChild("HumanoidRootPart")then return npc end
   end
  end
  return nil
 end
 if name=="Kuro"then
  for _,npc in ipairs(workspace.Living:GetChildren())do
   local h=npc:FindFirstChildOfClass("Humanoid")
   if(npc.Name=="Kuro"or npc.Name=="Kuro of a Hundred Plans")and h and h.Health>0 and npc:FindFirstChild("HumanoidRootPart")then return npc end
  end
 end
 return T.FindBoss(self,name)
end
function B:FinishFarm()
 self:Check()
 if S.active or S.loot or S.activityOwner then K:FinishFarm(function()return self:Continue()end)end
 self:Check();S:Stop("Manual boss transition");self:SetStage("prepare");self:RefreshCharacter()
end
function B:Equip(uuid)
 self:FinishFarm();assert(K:EquipAbility(uuid,function()return self:Continue()end).confirmed,"Farming Ability equip unconfirmed") self:RefreshCharacter()
end
function B:Farm(profile,status,data)
 self.combatGroup=false;self.combatProfile=self:CombatProfileFor(p.Data.Ability.Value,self.selected)
 self:SetStage("farm")
 if S.mobName~=profile then self:FinishFarm();self:SetStage("farm");S:SetMobName(profile)end
 if not S.active then S.home=nil;S.questTarget=nil;S:Start()end
 self:RecordBossAction(status or "Farming prerequisites",data)
end
function B:PrepareArrowStorage(amount)
 while true do
  self:Check();local stock=K:Snapshot();local missing=math.max(0,amount-(stock.stored.ITEM_1 or 0))
  local inv=game.ReplicatedStorage.ReplicatedModules.KnitPackage.Knit.Services.InventoryService.RF
  local capacity=inv.GetCapacity:InvokeServer("ItemInventory")
  assert(type(capacity)=="table"and type(capacity.CurrentCapacity)=="number"and type(capacity.MaxCapacity)=="number","Item capacity unavailable")
  if capacity.MaxCapacity-capacity.CurrentCapacity>=missing then return end
  self.status="Waiting for item storage space";task.wait(1)
 end
end
function B:ReconcileDialogue()
 local pending=self.pending;if not pending then return true end
 if pending.kind=="store-arrows"then
  local stock=K:Snapshot();local stored,total,retained=0,0,0
  local items=game.ReplicatedStorage.ReplicatedModules.KnitPackage.Knit.Services.InventoryService.RF.GetItems:InvokeServer("ItemInventory")
  for uuid in pairs(pending.uuids)do
   total+=1;if stock.uuids[uuid]and not items[uuid]then retained+=1 end
   if items[uuid]then stored+=1 end
  end
  if stored==total or(stored==0 and retained==total)then self.pending=nil;self:RecordBossAction("Storage reconciled",{});return true end
 elseif pending.kind=="summon"then
  if pending.serverJob==game.JobId and self:FindBoss(pending.boss)then self.pending=nil;self:RecordBossAction("Summon reconciled",{});return true end
 elseif pending.kind=="dialogue"then
  local q=K:QuestState(pending.id,false,true)
  local metadata=q.info and q.info.Metadata
  if(pending.id=="Slayer_Quest"and metadata and metadata.Slayer==pending.argument)
   or(pending.id~="Slayer_Quest"and Http:JSONEncode(q.info)~=pending.before)then
   self.pending=nil;self:RecordBossAction("Quest receipt reconciled",{});return true
  end
  if pending.id=="Slayer_Quest"and metadata and metadata.Slayer and metadata.Slayer~=pending.argument then
   self:Check();self.pending=nil;self:RecordBossAction("Slayer acceptance superseded by another contract",{});return true
  end

  local hasSlayerXP=false
  for key in pairs(metadata or{})do if type(key)=="string"and key:match("^%[.-%] Slayer XP$")then hasSlayerXP=true end end
  local catalogue=not hasSlayerXP and pending.id=="Slayer_Quest"and metadata and type(metadata.Slayers)=="table"
   and metadata.Slayers[pending.argument]and not metadata.Slayer and #(q.tasks or{})==0
   and metadata["["..tostring(pending.argument).."] Slayer XP"]==nil
   and not q.info.Completed and(q.info.Step==nil or q.info.Step==1)
  if catalogue and os.time()-(pending.time or os.time())>=8 then
   self:Check()
   if not pending.emptyCatalogueAt then
    pending.emptyCatalogueAt=os.time();self:RecordBossAction("Verifying unaccepted Slayer contract",{})
   elseif os.time()-pending.emptyCatalogueAt>=3 then
    self:Check();self.pending=nil;self.dialogueDue=os.clock()+(K.questRequestInterval or 1)
    self:RecordBossAction("Slayer contract not installed; retry scheduled",{});return true
   end
  elseif pending.emptyCatalogueAt then
   pending.emptyCatalogueAt=nil;self:RecordBossAction("Waiting for Slayer receipt",{})
  end
 end
 error("Previous boss action has no confirmed receipt; no duplicate request sent")
end
function B:Dialogue(id,argument)
 self:FinishFarm();self:Check();self:ReconcileDialogue()
 if id=="Slayer_Quest"then
  local cleared=K:ClearConflictingSlayer(argument,function()return self:Continue()end)
  self:Check();if cleared.status~="ready"then self.dialogueDue=os.clock()+(K.questRequestInterval or 1);return false end
 end
 if os.clock()<(self.dialogueDue or 0)then return false end
 local before=K:QuestState(id)
 self.pending={kind="dialogue",id=id,argument=argument,before=Http:JSONEncode(before.info),serverJob=game.JobId,time=os.time()}
 self:RecordBossAction("Preparing boss quest",{id=id})
 local reply=K:QuestDialogue(id,argument);self:Check()

 local slayer=id=="Slayer_Quest"
 if reply==false or type(reply)=="number"or(slayer and reply==nil)then
  self.pending=nil;self.dialogueDue=os.clock()+(K.questRequestInterval or 1)
  local seconds=type(reply)=="number"and math.max(0,reply)or nil
  self:RecordBossAction(slayer and(seconds and("Slayer cooldown: "..math.ceil(seconds).."s; retry in 1s")or"Slayer request rejected; retry in 1s")or"Waiting for native quest cooldown",{id=id,cooldown=seconds})
  local panel=getgenv().UmbrellaFreePanel
  if slayer and seconds and panel and panel.alive and panel.engine==S and panel.NotifyQuestCooldown then pcall(panel.NotifyQuestCooldown,panel,argument,seconds)end
  return false
 end
 local deadline=os.clock()+5
 repeat
  self:Check();local q=K:QuestState(id);local metadata=q.info and q.info.Metadata
  if(id=="Slayer_Quest"and metadata and metadata.Slayer==argument)
   or(id~="Slayer_Quest"and Http:JSONEncode(q.info)~=self.pending.before)then
   self.pending=nil;self:RecordBossAction("Boss quest ready",{id=id});return true
  end
  task.wait(.1)
 until os.clock()>deadline
 error("Boss quest outcome unconfirmed; native journal retained")
end
function B:PrepareSlayer(name,fodder)
 while not self:FindBoss(self.selected)do
  self:Check()
  local q=K:QuestState("Slayer_Quest");local metadata=q.info and q.info.Metadata or{}
  if metadata.Slayer and metadata.Slayer~=name then
   self:Dialogue("Slayer_Quest",name);task.wait(K.questRequestInterval or 1)
  elseif metadata.Slayer~=name then
   self:Dialogue("Slayer_Quest",name);task.wait(.1)
  else self:Farm(fodder,"Farming "..fodder.." for "..self.selected);task.wait(.25)end
 end
 self:FinishFarm()
 return true
end
function B:PrepareKuro()
 local id="Save_The_Village_Adventure"
 self:Farm("Kuro","Preparing Save The Village")
 local q=K:QuestState(id)
 if not q.info or q.info.Completed then
  self:FinishFarm();self:Check()
  self.pending={kind="dialogue",id=id,before=Http:JSONEncode(q.info),serverJob=game.JobId,time=os.time()}
  self:RecordBossAction("Accepting Save The Village",{})
  local result=K:AcceptAdventure(id,function()return self:Continue()end)
  if result.status=="confirmed"or result.status=="existing"or result.status=="cooldown-or-unavailable"or result.status=="occupied"then
   self.pending=nil;self:RecordBossAction("Waiting for Kuro adventure",{status=result.status});return
  end
  error("Kuro acceptance unconfirmed; journal retained")
 end
 if q.info.Step==2 then self:Dialogue(id)
 elseif q.info.Step and q.info.Step>=3 then
  for _,objective in ipairs(q.tasks or{})do if objective.name=="Defeat Kuro"and objective.max and objective.value>=objective.max then self:Dialogue(id);break end end
 end
end
function B:SummonBoss(name)
 while not self:FindBoss(name)do
  self:Check()
  for _,alternate in ipairs({false,true})do if self:TrySummonBoss(name,alternate)then return end end
  self.status="Both boss arenas occupied; waiting";task.wait(5)
 end
end
function B:AwaitValentine()
 self:AtPose(S:ValentineWaitingPose(),function()
  while not self:FindBoss("Funny Valentine")do
   self:Check();self.status="Waiting for Funny Valentine spawn"
   local marker=workspace.Map.Locations:FindFirstChild("Devil's Palm Hole")
   self:StreamAround(marker and marker:GetPivot().Position or S:ValentineWaitingPose().Position,1)
   task.wait(1)
  end
 end)
end
function B:AwaitNatural(name)
 local entry=assert(self.natural[name],"Unknown natural boss")

 local pose=CFrame.new(table.unpack(entry.position))
 self:AtPose(pose,function()
  while not self:FindBoss(name)do
   self:Check();self.status="Waiting for "..name.." spawn"
   self:StreamAround(pose.Position,1);task.wait(.2)
  end
 end)
end
function B:AwaitKars()
 self:AtPose(CFrame.new(-1054.919,279.944,1311.260),function()
  while not self:FindBoss("Kars")do
   self:Check();self.status="Waiting for Kars (experimental Down)"
   self:StreamAround(Vector3.new(-1054.919,324.944,1311.260),1);task.wait(1)
  end
 end)
end
function B:Fight(name)
