 local h=npc:FindFirstChildOfClass("Humanoid");local root=npc:FindFirstChild("HumanoidRootPart")
 self:FinishFarm();self.combatProfile=self:CombatProfileFor(p.Data.Ability.Value,name);self:SetStage("farm")
 S:SetMobName("Curses");S.home=CFrame.new(root.Position);S.questTarget=npc
  local encounter={owner=self,boss=name}
  encounter.combatPosition=B:CombatFarmPosition(name,h.Health,h.MaxHealth)
  S.bossEncounter=encounter;S:Start()
 local died=false;local connection=h.Died:Connect(function()died=true end)
 local missing,progress,lastHP=nil,os.clock(),h.Health
 local ok,result=xpcall(function()
  while not died and h.Health>0 do
   self:Check()
   if S.bossEncounter==encounter then encounter.combatPosition=B:CombatFarmPosition(name,h.Health,h.MaxHealth)end
   if not npc.Parent or not npc:FindFirstChild("HumanoidRootPart")then
    missing=missing or os.clock();if os.clock()-missing>=8 then return false end
   else missing=nil end
   if h.Health<lastHP then lastHP=h.Health;progress=os.clock()end
   assert(os.clock()-progress<120,"Manual boss damage stopped progressing")
   self.status="Fighting "..name;task.wait(.2)
  end
  self:Check();return true
 end,debug.traceback)
 connection:Disconnect()
 if S.bossEncounter and S.bossEncounter.owner==self then S.bossEncounter=nil end
 S.questTarget=nil;S.questHoverTarget=nil;S.questHoverPose=nil
