 self:SetStage("prepare");self:ReconcileDialogue();self:Equip(self.farmingUUID)
 while self:Continue()do
  local ok,err=xpcall(function()
   self:Check();self:ReconcileDialogue()
   if not self:FindBoss(self.selected)then
    if self.selected=="Dio"or self.selected=="Diavolo"then self:SummonBoss(self.selected)
    elseif self.selected=="The Bearer"then self:PrepareSlayer("Finger Bearer","Curses")
    elseif self.selected=="Dio Brando"then self:PrepareSlayer("Dio Brando","Zombies")
    elseif self.selected=="Kuro"then self:PrepareKuro()
    elseif self.selected=="Funny Valentine"then self:AwaitValentine()
    elseif self.selected=="Kars"then self:AwaitKars()
    elseif self.natural[self.selected]then self:AwaitNatural(self.selected)end
   end
