 if S.active then S:StopManualFarm("Boss selection")end
 self.selected=name
end
function B:Start()

 assert(self.alive and not self.running and not self.worker,"Boss farm already running/stopping")
 assert(self:IsBoss(self.selected),"Choose a boss")
 assert(not S.active and not S.activityOwner and  true   and  true   and  true   and  true   and  true ,"Stop the current farming route first")
