 if S.bossEncounter and S.bossEncounter.owner==self then S.bossEncounter=nil end
 S.questTarget=nil;S:Stop("Manual boss stopped");self:ReleaseControls()
 if self.previousMob then S:SetMobName(self.previousMob);self.previousMob=nil end
