journals[scope]=journals[scope]or{}
local R={alive=true,busy=false,achievements=false,rewards=false,nextAchievement=0,nextRewards=0,pending=journals[scope],status="Ready",confirmed=0,serial={achievements=0,rewards=0}}
S.rewards=R
