end)() end
do local value=(function()
--!nocheck
local env=getgenv();local S=env.UmbrellaFree
local p=game.Players.LocalPlayer;local Http=game:GetService("HttpService")
local T={path="UmbrellaFree/teleports.json",entries={},builtin={}}
if S then S.teleport=T end
local function valid(entry)
    if type(entry)~="table"or type(entry.name)~="string"or #entry.name==0 or #entry.name>128
        or type(entry.placeId)~="number"or entry.placeId~=entry.placeId or entry.placeId<=0 or entry.placeId%1~=0
        or type(entry.pose)~="table"or(#entry.pose~=3 and #entry.pose~=12)then return false end
