local assetFiles={["PlusJakartaSans-Bold.ttf"]={name="5f5342ef7686-PlusJakartaSans-Bold.ttf",size=128988,data=""},["PlusJakartaSans-Medium.ttf"]={name="c77bab757d74-PlusJakartaSans-Medium.ttf",size=129180,data=""},["PlusJakartaSans-Regular.ttf"]={name="bd6276d4060e-PlusJakartaSans-Regular.ttf",size=128972,data=""},["PlusJakartaSans-SemiBold.ttf"]={name="65dbcedb6596-PlusJakartaSans-SemiBold.ttf",size=129288,data=""},["umbrella-mark.png"]={name="57d602830e4d-umbrella-mark.png",size=4609,data=""}}
local function decode(data)
 if crypt and type(crypt.base64decode)=="function"then return crypt.base64decode(data)end
 local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";local lookup={}
 for i=1,#alphabet do lookup[alphabet:byte(i)]=i-1 end
 local out={}
 for i=1,#data,4 do
  local a,b,c,d=data:byte(i,i+3);local value=lookup[a]*262144+lookup[b]*4096+(lookup[c]or 0)*64+(lookup[d]or 0)
  local bytes=string.char(math.floor(value/65536)%256,math.floor(value/256)%256,value%256)
  out[#out+1]=c==61 and bytes:sub(1,1)or d==61 and bytes:sub(1,2)or bytes
 end
 return table.concat(out)
end
local Brand={}
for key,file in pairs(assetFiles)do
 local path="UmbrellaFree/assets/"..file.name
 if not isfile(path)or #readfile(path)~=file.size then writefile(path,decode(file.data))end
 Brand[key]=getcustomasset(path)
end
local faces={}
for _,face in ipairs({{"Regular",400},{"Medium",500},{"SemiBold",600},{"Bold",700}})do faces[#faces+1]={name=face[1],weight=face[2],style="normal",assetId=Brand["PlusJakartaSans-"..face[1]..".ttf"]}end
local fontPath="UmbrellaFree/assets/PlusJakartaSans.font";writefile(fontPath,game:GetService("HttpService"):JSONEncode({name="Plus Jakarta Sans",faces=faces}))
Brand.font=getcustomasset(fontPath);Brand.logo=Brand["umbrella-mark.png"]

