-- Destination storage and an explicit one-shot test; no automatic event sender.
local function webhookURL(value)
 if type(value)~="string"then return nil end
 value=value:match("^%s*(.-)%s*$")
 if value==""then return ""end
 if #value>512 then return nil end
 local host,path=value:match("^https://([^/]+)(/.*)$")
 if host~="discord.com"and host~="discordapp.com"then return nil end
 if path:match("^/api/webhooks/%d+/[%w_%-]+$")or path:match("^/api/v%d+/webhooks/%d+/[%w_%-]+$")then return value end
 return nil
end
