  setthreadidentity(8) -- Native HTTP continuations can return below UI capability.
  local status=ok and type(response)=="table"and tonumber(response.StatusCode)
  webhookStatus:SetTitle(status and status>=200 and status<300 and"Test delivered"or(status and("HTTP "..status.."; not retried")or"Request failed; not retried"))
 end)
 return true
end
