local x=ui.internals
local Input,Run=x.Input,x.Run
local animate,bootAppearance=x.animate,x.bootAppearance
P.traitOverlayEnabled=bootAppearance.traitOverlay~=false
P.overlayLayout={x=.74,width=420,collapsed=false}
if type(bootAppearance.overlayLayout)=="table"then
 local v=bootAppearance.overlayLayout
 if type(v.x)=="number"and v.x==v.x then P.overlayLayout.x=math.clamp(v.x,0,1)end
 if type(v.width)=="number"and v.width==v.width then P.overlayLayout.width=math.clamp(v.width,160,4096)end
 P.overlayLayout.collapsed=v.collapsed==true
end
getgenv().UmbrellaFreePanel=P
local Http=game:GetService("HttpService")
local player=game.Players.LocalPlayer
local check,section,dropdown,columns=ui.check,ui.section,ui.dropdown,ui.columns
P.currencyEntries={{name="UCoins",symbol="uC",color="#F1CF58"},{name="DMC_RedOrbs",symbol="DMC:",color="#E04F5A"},{name="UShards",symbol="uS",color="#40BBEF"}}
local balances=P.headerSlot
local money={}
for i,entry in ipairs(P.currencyEntries)do
 local amount=entry.tintValue and('<font color="'..entry.color..'">…</font>')or"…"
 money[entry.name]=new("TextLabel",{Name=entry.name,Text='<font color="'..entry.color..'">'..entry.symbol..'</font>  '..amount,RichText=true,Font=Enum.Font.BuilderSans,TextSize=15,TextColor3=Color3.fromRGB(231,231,235),BackgroundTransparency=1,Position=UDim2.fromScale((i-1)/#P.currencyEntries,0),Size=UDim2.fromScale(1/#P.currencyEntries,1),ZIndex=21},balances)
end
P.balances=money
local currencyDirty=true
local currencyRemote=game.ReplicatedStorage.ReplicatedModules.KnitPackage.Knit.Services.ShopService
connect(currencyRemote.RE.CurrencyUpdated.OnClientEvent,function(kind)if kind=="Changed"then currencyDirty=true end end)
local function abbreviated(value)
 if value>=1e9 then return string.format("%.2fB",value/1e9):gsub("%.?0+B$","B")end
 if value>=1e6 then return string.format("%.2fM",value/1e6):gsub("%.?0+M$","M")end
 if value>=1e3 then return string.format("%.1fK",value/1e3):gsub("%.?0+K$","K")end
 return tostring(math.floor(value))
end
task.spawn(function()
 local last=0
 while P.alive do
  if currencyDirty or os.clock()-last>30 then
   currencyDirty=false;last=os.clock()
   for _,entry in ipairs(P.currencyEntries)do
    local ok,value=pcall(function()return currencyRemote.RF.GetCurrencyType:InvokeServer(entry.name)end)
    if not P.alive then return end
    if ok and type(value)=="number"then
     local amount=abbreviated(value);if entry.tintValue then amount='<font color="'..entry.color..'">'..amount..'</font>'end
     money[entry.name].Text='<font color="'..entry.color..'">'..entry.symbol..'</font>  '..amount;money[entry.name]:SetAttribute("Balance",value)
    end
   end
  end
  task.wait(.5)
 end
end)

local bindings={}
local function guard(fn)return function(...)
 local ok,err=pcall(fn,...)
 if not ok then ui.WindUI:Notify({Title="Umbrella Free",Content=tostring(err),Duration=5})end
end end
local function toggle(parent,title,key,get,set,priority)
 local c=check(parent,title,get(),guard(set))
 bindings[key]={get=get,set=set,control=c,kind="boolean",priority=priority or 1}
 return c
end
local function choice(parent,title,key,values,get,set,multi)
 local c=dropdown(parent,{Title=title,Values=values,Value=get(),Multi=multi,Callback=guard(set)})
 bindings[key]={get=get,set=set,control=c,kind=multi and "table"or "string",priority=0,values=values}
 return c
end
local function slider(parent,title,key,low,high,get,set)
 local c=parent:Slider({Title=title,Step=1,Value={Min=low,Max=high,Default=get()},Callback=guard(set)})
 bindings[key]={get=get,set=set,control=c,kind="number",priority=0,low=low,high=high}
 return c
end
