function P:LayoutTraitOverlay(viewport)
 local maximum=math.max(1,viewport.X);local width=math.clamp(self.overlayLayout.width,math.min(160,maximum),maximum)
 local center=math.clamp(self.overlayLayout.x*maximum,width/2,maximum-width/2)
 local collapsed=self.overlayLayout.collapsed
 local height=math.max(32,self.traitOverlayLabel.TextBounds.Y+10)
 if self.overlayTargetCollapsed~=collapsed then
  local initial=self.overlayTargetCollapsed==nil;self.overlayTargetCollapsed=collapsed
  self.overlayTransitionUntil=initial and 0 or os.clock()+.2
  if initial then self.traitOverlay.Position=UDim2.fromOffset(center,collapsed and -height or 0)
  else animate(self.traitOverlay,{Position=UDim2.fromOffset(center,collapsed and -height or 0)},.2)end
 elseif os.clock()>=(self.overlayTransitionUntil or 0)then self.traitOverlay.Position=UDim2.fromOffset(center,collapsed and -height or 0)end
 self.traitOverlay.Size=UDim2.fromOffset(width,height)
 self.traitOverlay.BackgroundTransparency=.18
 self.traitOverlayBorder.Enabled=true;self.overlayPull.Visible=collapsed
 self.traitOverlayLabel.Visible=true;self.overlayDrag.Visible=not collapsed;self.overlayResize.Visible=not collapsed
 self.overlayArrowLeft.Rotation=collapsed and 45 or -45;self.overlayArrowRight.Rotation=collapsed and -45 or 45
end
function P:BeginOverlayGesture(mode,input)
 if not self.traitOverlayEnabled or self.overlayLayout.collapsed then return end
 if input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch then return end
 self.overlayGesture={mode=mode,startX=input.Position.X,startY=input.Position.Y or 0,moved=false,center=self.traitOverlay.AbsolutePosition.X+self.traitOverlay.AbsoluteSize.X/2,width=self.traitOverlay.AbsoluteSize.X,touch=input.UserInputType==Enum.UserInputType.Touch and input or nil}
end
function P:MoveOverlayGesture(x,viewport,y)
 local gesture=self.overlayGesture;if not gesture then return end
 local maximum=math.max(1,viewport.X);local delta=x-gesture.startX
 if math.abs(delta)>5 or math.abs((y or gesture.startY)-gesture.startY)>5 then gesture.moved=true end
 if not gesture.moved then return end
 if gesture.mode=="resize"then
  local left=math.clamp(gesture.center-gesture.width/2,0,maximum-1)
  local width=math.clamp(gesture.width+delta,math.min(160,maximum-left),maximum-left)
  self.overlayLayout.width=width;self.overlayLayout.x=(left+width/2)/maximum
 else local half=math.min(gesture.width,maximum)/2;self.overlayLayout.x=math.clamp(gesture.center+delta,half,maximum-half)/maximum end
 self:LayoutTraitOverlay(viewport)
end
connect(P.overlayDrag.InputBegan,function(input)P:BeginOverlayGesture("drag",input)end)
connect(P.overlayResize.InputBegan,function(input)P:BeginOverlayGesture("resize",input)end)
connect(P.overlayPull.Activated,function()
 P.overlayGesture=nil;P.overlayLayout.collapsed=not P.overlayLayout.collapsed
