  P.overlayGesture=nil
  if gesture.mode=="drag"and not gesture.moved then P.overlayLayout.collapsed=true;P:LayoutTraitOverlay(workspace.CurrentCamera.ViewportSize)end
  P:SaveAppearance()
 end
end)
