 all.configs[name]=nil;writefile(configPath,Http:JSONEncode(all))
end
function P:CaptureConfig()
 local data={schema=1,values={},theme=self.activeTheme}
 for key,b in pairs(bindings)do data.values[key]=b.get()end

 return data
end
function P:ApplyConfig(data)
 if type(data)=="string"then data=assert(bank().configs[data],"Choose a saved config")end
 assert(type(data)=="table"and data.schema==1 and type(data.values)=="table","Invalid FREE config")
 data=table.clone(data);data.values=table.clone(data.values)
 if data.values.resetConditions~=nil then
  assert(type(data.values.resetConditions)=="table","Invalid old reset settings")
  if data.values.busoReset==nil then data.values.busoReset=table.find(data.values.resetConditions,"Buso Cooldown")~=nil end
  data.values.resetConditions=nil
 end
 if data.theme then assert(table.find(self.themes,data.theme),"Unknown saved theme")end
 local ordered={}
 for key,value in pairs(data.values)do
  local b=assert(bindings[key],"Unknown FREE setting: "..tostring(key))
  assert(type(value)==b.kind,"Invalid setting type: "..key)
  if key=="abilityQueue"then for _,id in pairs(value)do assert(type(id)=="string"and #id>0,"Invalid ability UUID")end end
  if b.kind=="number"then assert(value==value and value>=b.low and value<=b.high,"Invalid numeric setting")end
  if b.values then for _,v in ipairs(b.kind=="table"and value or{value})do assert(table.find(b.values,v),"Unknown selection: "..key)end end
  ordered[#ordered+1]={key=key,b=b,value=value}
 end
 table.sort(ordered,function(a,b)return a.b.priority<b.b.priority end)
 assert(not S.lifecycle.busy and not(S.inventoryOps and S.inventoryOps.busy),"Wait for the current operation to finish")
 S.resources:SetEnabled(false)
 S.statRoll:Stop("Config loaded");S.traits:Stop("Config loaded")
 S:StopManualFarm("Config loaded")
 if data.theme then self:ApplyTheme(data.theme,true)end
 for _,entry in ipairs(ordered)do
  entry.b.set(entry.value)
  local c=entry.b.control
  if entry.b.kind=="boolean"then c:Set(entry.value,false)elseif c.Select then c:Select(entry.b.display and entry.b.display()or entry.value)elseif c.Set then c:Set(entry.value)end
 end
end
function P:LoadConfig(data)
 assert(not self.loadingConfig,"A config is already loading")
 self.loadingConfig=true
 local ok,result=pcall(function()return self:ApplyConfig(data)end)
 self.loadingConfig=false
 if not ok then error(result,0)end
 return result
end
function P:SaveConfig(name)
 name=tostring(name or ""):match("^%s*(.-)%s*$")
 assert(#name>0 and #name<=64,"Enter a config name (1-64 characters)")
 local all=bank();local data=self:CaptureConfig()
 all.configs[name]=data;writefile(configPath,Http:JSONEncode(all))
 local saved=bank().configs[name]
 local function same(a,b)
  if type(a)~=type(b)then return false end
  if type(a)~="table"then return a==b end
  for key,value in pairs(a)do if not same(value,b[key])then return false end end
  for key in pairs(b)do if a[key]==nil then return false end end
  return true
 end
 assert(same(data,saved),'Config save not confirmed: "'..name..'"')
