local function beginDrag(input,mode)
 if input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch then return end
 if Q.tween then Q.tween:Cancel()end
 local vp=workspace.CurrentCamera.ViewportSize
 local width,height=root.Size.X.Offset,root.Size.Y.Offset

 local x=root.Position.X.Scale*vp.X+root.Position.X.Offset-width*root.AnchorPoint.X
