 drag={input=input,mode=mode,point=Vector2.new(input.Position.X,input.Position.Y),size=Vector2.new(width,height),top=top,x=x,
  scaleX=math.max(.01,root.AbsoluteSize.X/width),scaleY=math.max(.01,root.AbsoluteSize.Y/height),
  horizontal=Q.placement=="Top"or Q.placement=="Bottom",edge=Q.placement,left=Q.placement:sub(1,4)=="Left"}
end
connect(grip.InputBegan,function(input)beginDrag(input,"bottom")end)
connect(topGrip.InputBegan,function(input)beginDrag(input,"top")end)
