connect(game:GetService("UserInputService").InputChanged,function(input)
 if reorder and(input.UserInputType==Enum.UserInputType.MouseMovement or input==reorder.input)then
  if os.clock()-reorder.started>=.18 and math.abs(input.Position.Y-reorder.y)>5 then
   Q.suppressActionUntil=os.clock()+.5
   reorder.moved=true
   local dragged=reorder.row;local center=input.Position.Y
   dragged.frame.LayoutOrder=math.floor(center-list.AbsolutePosition.Y+list.CanvasPosition.Y)
   for _,row in ipairs(Q.rows)do if row~=dragged and not row.empty then row.frame.LayoutOrder=math.floor(row.frame.AbsolutePosition.Y-list.AbsolutePosition.Y+list.CanvasPosition.Y+17)end end
  end
  return
 end
 if not drag or(input.UserInputType~=Enum.UserInputType.MouseMovement and input~=drag.input)then return end
 local delta=Vector2.new((input.Position.X-drag.point.X)/drag.scaleX,(input.Position.Y-drag.point.Y)/drag.scaleY)
 if delta.Magnitude<3 then return end
 local vp=workspace.CurrentCamera.ViewportSize
 if drag.mode=="move"then
  if math.abs(drag.horizontal and delta.X or delta.Y)<5 then return end
  Q.suppressCollapseUntil=os.clock()+1
  Q.centerRatio=drag.horizontal and((drag.x+drag.size.X/2+delta.X)/vp.X)or((drag.top+drag.size.Y/2+delta.Y)/vp.Y)
 elseif drag.horizontal then
  Q.width=math.clamp(drag.size.X+(drag.mode=="top"and -delta.X or delta.X),180,math.max(180,math.min(600,vp.X-32)))
  Q.height=math.clamp(drag.size.Y+(drag.edge=="Top"and delta.Y or -delta.Y),100,math.max(100,math.min(900,vp.Y-24)))
  Q.centerRatio=(drag.mode=="top"and(drag.x+drag.size.X-Q.width/2)or(drag.x+Q.width/2))/vp.X
 else
  Q.width=math.clamp(drag.size.X+(drag.left and delta.X or -delta.X),180,math.max(180,math.min(600,vp.X-32)))
  Q.height=math.clamp(drag.size.Y+(drag.mode=="top"and -delta.Y or delta.Y),100,math.max(100,math.min(900,vp.Y-24)))
  Q.centerRatio=(drag.mode=="top"and(drag.top+drag.size.Y-Q.height/2)or(drag.top+Q.height/2))/vp.Y
 end
 Q:Refresh()
end)
connect(game:GetService("UserInputService").InputEnded,function(input)
